DO $$
DECLARE
  invu_id uuid := 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c'::uuid;
BEGIN

  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'INVU no es un POS, es un Ecosistema', 'INVU POS no es simplemente un sistema de facturación o un software de punto de venta. Es un ecosistema operativo completo diseñado para centralizar, automatizar y potenciar todas las áreas críticas de un negocio comercial: ventas, inventarios, producción, marketing, fidelización y análisis de datos. Funciona como el cerebro digital de la operación, conectando sucursales, equipos, clientes y procesos en una sola plataforma sincronizada. Cuando un vendedor entiende esto, deja de vender un "software" y comienza a vender una solución de transformación digital.', 'Un vendedor llega a un restaurante con 3 sedes y el dueño le dice: "Ya tengo un POS que me factura". El vendedor responde: "No estoy aquí para venderte otro POS. Estoy aquí para mostrarte cómo puedes centralizar tus 3 sedes en un solo panel, sincronizar tu inventario en tiempo real, y ver reportes consolidados de rentabilidad por sede desde tu celular. INVU no es un POS, es el cerebro digital de tu operación." El dueño, que antes veía a INVU como un reemplazo de su sistema, ahora lo ve como una herramienta de crecimiento.', NULL, NULL, NULL, 1);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Diferencia entre Característica y Beneficio', 'Una característica es lo que el sistema tiene. Un beneficio es lo que el cliente gana. El vendedor de nivel básico enumera características; el vendedor de nivel Gravity traduce cada característica en un beneficio que resuelve un dolor específico del cliente. La fórmula es: "Esto significa que...", "Por qué importa...", "Qué problema evita...", "Qué beneficio genera..."', 'Característica: "INVU tiene facturación electrónica nativa."  
Beneficio: "Eso significa que no pagas S/89-149 mensuales a Nubefact o Efact. Este ahorro mensual ya cubre gran parte de la diferencia de precio con otros sistemas. Además, tu facturación está integrada con el inventario, así que cada factura actualiza tu stock automáticamente."  
El cliente no compra la característica; compra el ahorro y la integración.', NULL, NULL, NULL, 2);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Diagnóstico es el Primer Paso (y el más importante)', 'El primer paso en cualquier interacción comercial es escuchar más de lo que se habla. Hacer preguntas abiertas para entender la operación actual del cliente, sus dolores, objetivos y limitaciones. No se trata de vender INVU, se trata de entender al negocio para luego ofrecer la solución que realmente necesita. Si no diagnosticas, estás vendiendo a ciegas.', 'Un vendedor inicia una llamada: "Hola, soy de INVU. Permíteme hacerte unas preguntas para entender tu negocio: ¿Cuántas sedes tienes? ¿Qué sistema usas hoy para facturar e inventario? ¿Cómo manejas la facturación electrónica? ¿Tienes recetas costeadas? ¿Usas delivery?" Luego de 5 minutos de preguntas, el vendedor identifica que el cliente tiene 3 sedes, paga Nubefact aparte y no tiene control de inventario centralizado. Ahora sabe exactamente qué dolor atacar y qué módulos de INVU mostrar. Sin el diagnóstico, habría hecho una demo genérica y perdido la oportunidad.', NULL, NULL, NULL, 3);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Las 7 Preguntas que Todo Vendedor Debe Hacer', 'Existen 7 preguntas de diagnóstico que revelan si el cliente califica, qué setup aplicar, qué licencias cotizar y cuál es el argumento de valor principal. Estas preguntas son la brújula del vendedor. Sin ellas, estás navegando sin mapa.', 'En una reunión con un dueño de restaurante, el vendedor hace las 7 preguntas en 5 minutos:  
"¿Cuánto facturan al mes y cuántas sedes tienen?" → S/120,000, 3 sedes.  
"¿Qué sistema usan hoy y qué los hace cambiar?" → POS básico, no centraliza.  
"¿Cómo emiten su factura electrónica?" → Nubefact, S/120/mes por sede.  
"¿Tienen recetas costeadas y control de inventario?" → No, operan a ciegas.  
"¿Cuántas cajas necesitan por sucursal?" → 2 por sede.  
"¿Manejan delivery propio o solo apps?" → Rappi, pagan 25% comisión.  
"¿Quién toma la decisión y cuándo necesitan estar arriba?" → El dueño, en 2 semanas.  
Con estas respuestas, el vendedor sabe que necesita cotizar INVU Central + 3 licencias Sucursal + KDS + QR + Loyalty, y que el argumento principal será centralización y ahorro en PSE.', NULL, NULL, NULL, 4);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Poder del Onboarding Consultivo', 'INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación limpia y rentable desde el día del go live. Se trabaja con el dueño para que el sistema refleje un negocio rentable: menú completo categorizado, recetas con costo por plato, materia prima y proveedores, métodos de pago y propinas, roles y permisos, descuentos y promociones, reportes y dashboards. Desde el primer ticket, el cliente ve su margen real, su inventario y su costo por plato. Esto transforma al vendedor en un consultor de confianza.', 'Un vendedor le dice al dueño: "No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca había visto el margen real de sus platos, percibe a INVU como un socio, no como un proveedor.', NULL, NULL, NULL, 5);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Valor del Soporte Local 24/7', 'INVU tiene equipo de soporte en Perú, en horario Perú, con atención por WhatsApp directo a un humano, soporte remoto y en sitio. Cuando el sistema falle un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. Esto no es un lujo; es una necesidad crítica para la continuidad del negocio.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El vendedor responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma y está en tu mismo huso horario. Te paso el WhatsApp del equipo técnico antes de firmar." El cliente se siente seguro.', NULL, NULL, NULL, 6);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Framework Gravity – 5 Pasos para Vender con Autoridad', 'El Framework Gravity es un proceso de 5 pasos que convierte al vendedor en un asesor de confianza: Diagnóstico (escucha), Educación (explica la lógica), Comparación (con datos concretos), Construcción de Valor (cuantifica beneficios), Cierre (pregunta que avanza el proceso). No es un guion rígido; es una secuencia lógica que guía al cliente desde la duda hasta la decisión.', 'Un vendedor aplica Gravity en una llamada de 20 minutos:  
Diagnóstico (5 min): Hace las 7 preguntas.  
Educación (5 min): "INVU incluye FE nativa, así que te ahorras S/360/mes en Nubefact."  
Comparación (5 min): "Tu costo actual es S/1,110/mes. Con INVU, S/1,862/mes, pero incluye centralización y fidelización."  
Construcción de Valor (5 min): "Si reducimos tus mermas en un 2%, ahorras S/2,400/mes. La inversión se paga sola."  
Cierre: "¿Qué información necesitas para tomar la decisión?" El cliente pide la cotización.', NULL, NULL, NULL, 7);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Protocolo Gravity para Manejar Objeciones', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity tiene 5 pasos: Escucha/Valida (reconoce la preocupación), Diagnostica (pregunta para entender el origen), Reencuadra (reformula como oportunidad), Micro-cierre (obtén un pequeño compromiso), Cierre (avanza al siguiente paso). No es una batalla; es una danza.', 'Cliente: "Es caro."  
Vendedor:  
Valida: "Entiendo que el precio es una consideración importante."  
Diagnostica: "¿Qué es lo que te parece caro exactamente, el setup o las licencias mensuales?"  
Reencuadra: "Cuando sumas lo que pagas por Nubefact (S/120/mes), soporte (S/80/mes) y sistemas separados, el costo real de la competencia es S/450/mes. INVU es S/350/mes todo incluido."  
Micro-cierre: "¿Te parece si hacemos el cálculo con tus números actuales?"  
Cierre: "¿Qué día te acomoda para la demo?"', NULL, NULL, NULL, 8);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Comparación con Datos, no con Opiniones', 'El vendedor debe comparar INVU con las alternativas del mercado desde una posición de autoridad, no defensiva. Se explica qué ofrecen los sistemas básicos, dónde fallan y por qué INVU es superior en integración, escalabilidad, soporte y costo a largo plazo. La comparación se hace con datos concretos, no con opiniones.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo (Nubefact/Efact) y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia te cobra por actualizaciones, por visitas técnicas, y no incluye módulos de marketing ni e-commerce sin comisiones. Esa diferencia de S/100 al mes es el 0.2% de tu facturación. ¿Vale la pena ahorrar S/100 al mes a cambio de perder centralización, integración y soporte 24/7?"', NULL, NULL, NULL, 9);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Ritmo del Vendedor Ganador (Hunters)', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base (S/2,958) + comisiones (S/490) + bono (S/850) + MRR (S/252) = S/4,550. El esfuerzo se traduce en dinero. El que no visita, no vende.', NULL, NULL, NULL, 10);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Escalera Base – Protección y Motivación', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas, reconociendo el esfuerzo de cerrar cuentas grandes.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258 (S/850 + S/408 de viáticos). No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', NULL, NULL, NULL, 11);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Comisión MRR – Ingresos Pasivos que se Construyen', 'Desde la cuarta venta, el Hunter gana 3% MRR mensual sobre las licencias activas de sus clientes durante 12 meses. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional. Esto es lo que convierte un ingreso de "cazador" en un ingreso de "agricultor".', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin que el Hunter haga nada adicional. La cola MRR es la jubilación del vendedor.', NULL, NULL, NULL, 12);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Visita Técnica como Herramienta de Ventas', 'La visita técnica no es un simple trámite de instalación. Es una herramienta estratégica de consultoría que se sitúa entre la demo y la cotización, permitiendo al Hunter demostrar profesionalismo, identificar necesidades adicionales de hardware y garantizar una implementación exitosa. La visita técnica valida la red, el hardware y la distribución del local, y genera un informe que el Hunter usa para justificar la inversión total (software + hardware). Es un diferenciador clave frente a la competencia.', 'Un Hunter agenda la visita técnica para un restaurante. El especialista de INVU descubre que el WiFi no llega a la cocina, que la impresora es obsoleta, y que el internet es coaxial (lento). El informe técnico recomienda: router Mesh WiFi, impresora 3nStar RPT004, y fibra óptica. El Hunter incluye esto en la cotización, sumando S/1,500 en hardware adicional. Su comisión (10% desde la 4ª venta) aumenta en S/150. Además, el cliente tiene certeza de que el sistema funcionará sin problemas. El Hunter cierra con autoridad.', NULL, NULL, NULL, 13);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Regla de "Venta Grande Vale por Tres"', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (por ejemplo, una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas. El sistema premia ir por lo grande.', NULL, NULL, NULL, 14);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', NULL, NULL, NULL, 15);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El ROI – Cómo Justificar la Inversión con Números', 'El valor no está en el precio, está en lo que el cliente gana. El vendedor debe cuantificar los beneficios: horas de trabajo ahorradas, errores de inventario reducidos, ventas incrementadas, control financiero consolidado y tranquilidad. Calcular el retorno de inversión (ROI) en meses es la herramienta más poderosa para cerrar.', 'Un restaurante factura S/50,000/mes. Con INVU, reduce mermas en un 2% (S/1,000/mes), ahorra S/120/mes en PSE externo, y aumenta ventas en un 5% con QR y Loyalty (S/2,500/mes). Ahorro total: S/3,620/mes. La inversión en INVU es S/350/mes. El ROI es del 934%. El retorno de inversión se da en menos de 1 mes. Con estos números, el cliente no puede decir "es caro".', NULL, NULL, NULL, 16);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Los 3 Tipos de Clientes y Cómo Venderles', 'Existen 3 tipos de clientes: el que no sabe que necesita INVU (hay que educar), el que sabe que necesita pero duda (hay que comparar), y el que está listo para comprar (hay que cerrar). El vendedor debe identificar en qué etapa está cada cliente y adaptar su estrategia. No se vende igual a un cliente que no sabe que existe la facturación electrónica nativa que a uno que ya la conoce.', 'Cliente tipo 1 (no sabe): "¿Sabías que la SUNAT exige facturación electrónica y que la mayoría de POS te cobran aparte por eso? INVU ya la incluye."  
Cliente tipo 2 (sabe pero duda): "Has visto otras opciones. ¿Qué te ofrecen que INVU no tenga? Yo te muestro la diferencia."  
Cliente tipo 3 (listo): "¿Qué información necesitas para firmar? ¿Te parece si empezamos con el setup la próxima semana?"', NULL, NULL, NULL, 17);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Rol del Vendedor como Asesor de Confianza', 'El vendedor de Gravedad Cero no solo vende INVU, sino que se convierte en un asesor de confianza del cliente. Controla toda la conversación desde el diagnóstico hasta el cierre sin perder el control. El cliente siente que está tomando la decisión, pero en realidad el vendedor ha guiado cada paso. El cierre no es forzado; es el resultado natural de una conversación donde no comprar INVU parece una mala decisión comercial.', 'Un cliente dice: "Lo voy a pensar."  
El vendedor responde: "Es normal. Lo que muchos clientes me dicen es que después de pensarlo, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos. Si no, te paso un caso de un cliente parecido al tuyo." El cliente, que estaba a punto de irse, se queda y pide la cotización.', NULL, NULL, NULL, 18);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Pitch de 30 Segundos que Enamora', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?"', '"INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable."  
El cliente, que ha estado batallando con su POS actual, dice: "¿Cómo lo vemos?" El vendedor ya tiene la reunión.', NULL, NULL, NULL, 19);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Los Errores que Matan la Venta', 'Hay 6 errores comunes que el vendedor debe evitar: (1) Hablar de precio antes de crear valor, (2) No diagnosticar, (3) No explicar las diferencias técnicas, (4) No comparar, (5) No cerrar, (6) Hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza".', 'Un cliente pregunta: "¿Cuánto cuesta?"  
El vendedor novato responde: "S/350/mes."  
El cliente dice: "Es caro." Se va.  
El vendedor experto responde: "El costo depende de tus necesidades. Permíteme hacerte algunas preguntas para entender tu operación y darte una cotización precisa. ¿Cuántas sedes tienes? ¿Qué sistema usas hoy?" El cliente se queda, responde, y el vendedor construye valor antes de dar el precio. La venta avanza.', NULL, NULL, NULL, 20);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Multiplataforma – Libertad para el Cliente', 'INVU funciona en iOS, Android y Windows, permitiendo operar desde tablets, computadoras o dispositivos móviles. Esto da al negocio la libertad de elegir el equipo que mejor se adapte a su operación, sin estar atado a un proveedor específico. El vendedor debe comunicar esto como un ahorro y una ventaja, no como un dato técnico.', '"No te vamos a decir qué dispositivo comprar. INVU funciona en iOS, Android y Windows. Usa la tablet que ya tienes, la computadora que prefieras, o el dispositivo que elijas. La libertad de elegir es parte de nuestro valor. Y con tablets, tu personal puede tomar pedidos en cualquier lugar del local." El cliente, que ya tiene tablets, se siente aliviado de no tener que comprar hardware nuevo.', NULL, NULL, NULL, 21);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Upgrade de los Programas de Referidos a Partners', 'El programa de Partners es una evolución del programa de Referidos. Mientras el referido cobra una comisión fija (S/500, S/1,000, S/1,500), el Partner cobra el 8% del valor total del primer año del cliente (setup + 12 mensualidades), pagado en tres tramos. El Partner tiene un incentivo para traer clientes más grandes, porque su comisión crece proporcionalmente. El referido es para contactos ocasionales; el Partner es para profesionales que quieren monetizar su red de contactos de manera recurrente.', 'Un contador refiere a un cliente de 1 sede: comisión S/532 (8% de S/6,650).  
Si el mismo contador refiere una cadena de 10 sedes: comisión S/6,057 (8% de S/75,708).  
El contador entiende que su red de contactos de clientes grandes vale mucho más. Se convierte en Partner y enfoca sus esfuerzos en las cuentas grandes.', NULL, NULL, NULL, 22);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al vendedor profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al vendedor con datos reales.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', NULL, NULL, NULL, 23);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Reutilización de Hardware – Confianza y Ahorro', 'Durante la visita técnica, el especialista de INVU evalúa el hardware existente del cliente (impresoras, lectores, cajones, tablets) y recomienda reutilizar todo lo que sea compatible. Esto ahorra dinero al cliente y construye confianza. El vendedor debe comunicar esto como un gesto de honestidad, no como una concesión.', 'El cliente dice: "No quiero comprar impresoras nuevas."  
El vendedor responde: "No vamos a obligarte a comprar hardware nuevo si lo que tienes funciona. Nuestro especialista va a revisar tus impresoras, lectores y cajones, y te va a recomendar reutilizar todo lo que sea compatible. Así ahorras en la inversión inicial y solo compras lo que realmente necesitas." El cliente confía en el vendedor porque no le está vendiendo algo que no necesita.', NULL, NULL, NULL, 24);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Router 4G de Respaldo – Seguro de Continuidad', 'Para comercios con alta demanda de delivery e integraciones, INVU recomienda un router con chip 4G de respaldo que asegura operación continua si el internet principal falla. El vendedor debe vender esto como un seguro, no como un lujo.', '"Tu internet puede fallar, pero tu negocio no debe detenerse. Por eso recomendamos un router con chip 4G de respaldo. Si el internet principal se cae, el sistema cambia automáticamente al respaldo y sigues operando sin perder una venta. Es tu seguro de continuidad." El cliente, que ha perdido ventas por cortes de internet, ve el valor inmediato y acepta la recomendación.

---

# PÍLDORAS DE CONOCIMIENTO - INVU POS LATINOAMÉRICA', NULL, NULL, NULL, 25);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'INVU es el Sistema Operativo del Comercio Latinoamericano', 'INVU POS no es un software importado y adaptado a la región. Nació en Latinoamérica y entiende su esencia: el acento, la forma de cobrar, la manera de atender, las ganas de crecer. Mientras que los sistemas extranjeros imponen lógicas de otros mercados, INVU habla el idioma del comercio latinoamericano. Cuando un vendedor comunica esto, no está vendiendo un sistema; está vendiendo una solución que respeta y potencia la identidad del negocio del cliente.', 'Un vendedor en Colombia le dice al dueño de un restaurante: "INVU no es un sistema diseñado en otro continente y traducido al español. Nació en Latinoamérica, entiende cómo se vive, se vende y se sueña aquí. Sabe que cada país tiene su acento, su forma de cobrar, su manera de atender. INVU habla tu idioma, no solo en castellano, sino en el idioma de tu negocio." El cliente, que ha probado sistemas importados que no entienden su realidad, se siente escuchado y confía.', NULL, NULL, NULL, 26);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Interfaz que No Obliga a Pensar, Permite Avanzar', 'INVU no obliga a leer manuales eternos ni a navegar en pantallas confusas. Todo está donde debe estar: menú personalizado, CRM de clientes, imágenes del menú, buscador de producto, divisor de cuentas al instante, KDS sin retrasos, control de ingreso de colaboradores y mapa de mesas. La interfaz no obliga a pensar, permite avanzar. Para el vendedor, esto significa que el cliente no tendrá una curva de aprendizaje larga; el sistema es intuitivo desde el día uno.', 'Un cliente objeta: "Mis empleados son mayores, no saben usar tecnología." El vendedor responde: "INVU está diseñado para que cualquiera lo use sin entrenamiento extenso. Todo está donde debe estar: el menú con imágenes, el buscador que encuentra cualquier producto en segundos, el divisor de cuentas que hace el cálculo automático. Tu personal no tiene que pensar en cómo funciona el sistema; solo tiene que usarlo. La interfaz no obliga a pensar, permite avanzar."', NULL, NULL, NULL, 27);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Integración Total vs. Caos de Múltiples Sistemas', 'Mientras otros sistemas obligan a manejar cinco plataformas distintas (POS, inventario, delivery, ecommerce, facturación), INVU integra todo en un solo lugar. Nada de saltar entre sistemas, nada de duplicar trabajo. INVU no cambia el flujo del negocio, lo mejora. El vendedor debe comunicar que la integración no es un lujo; es una necesidad para operar eficientemente en el entorno latinoamericano, donde el tiempo y los recursos son limitados.', '"No necesitas cinco sistemas diferentes para manejar tu negocio. Con INVU, delivery, inventario, ecommerce y facturación están en un solo lugar. Una venta en tu tienda física se refleja en tu inventario y en tus reportes sin que tengas que hacer nada. Tu operación se simplifica, no se complica. Deja de saltar entre sistemas y empieza a controlar todo desde un solo panel."', NULL, NULL, NULL, 28);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Flexibilidad de Hardware – Libertad para Elegir', 'INVU funciona sin problemas en iOS, Android y Windows, permitiendo operar desde tablets, computadoras o dispositivos móviles. Esto da al negocio la libertad de elegir el equipo que mejor se adapte a su operación, sin estar atado a un proveedor específico. El vendedor debe comunicar esto como un ahorro significativo: no hay que comprar hardware caro y específico; se puede usar lo que ya se tiene.', '"No te vamos a decir qué dispositivo comprar. INVU funciona en iOS, Android y Windows. Usa la tablet que ya tienes, la computadora que prefieras, o el dispositivo que elijas. La libertad de elegir es parte de nuestro valor. Y con tablets, tu personal puede tomar pedidos en cualquier lugar del local. No estás atado a un proveedor ni a un hardware costoso."', NULL, NULL, NULL, 29);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Ecosistema que Fideliza Clientes', 'INVU no solo procesa ventas; ayuda a que los buenos clientes siempre vuelvan con tarjetas perforadas y wallet digital, donde cada visita suma, cada compra deja huella y cada cliente siente que vale la pena regresar. El vendedor debe mostrar que INVU no es solo una herramienta de facturación, sino una máquina de retención de clientes.', '"Los buenos clientes siempre vuelven con INVU. El sistema de fidelización integra tarjetas perforadas y wallet digital: cada compra suma, el cliente ve su saldo en su celular, y tú ves cómo aumenta la recurrencia. El cliente gana, el negocio también. No pierdas más clientes que compran una vez y no regresan. INVU los trae de vuelta."', NULL, NULL, NULL, 30);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El POS que No Hace Esperar al Cliente', 'El POS de INVU está diseñado para la velocidad: menú personalizado, imágenes de productos, buscador, divisor de cuentas instantáneo. En Latinoamérica, donde las filas pueden ser largas y los clientes impacientes, la velocidad de atención es un diferenciador crítico. Un vendedor debe comunicar que INVU reduce el tiempo de atención y aumenta la satisfacción del cliente.', '"Con INVU, tu personal no tiene que pensar en cómo funciona el sistema. Todo está donde debe estar: el menú con imágenes, el buscador que encuentra cualquier producto en segundos, el divisor de cuentas que hace el cálculo automático. Tu equipo avanza rápido, las filas se mueven, y tus clientes no esperan. Menos estrés, más ventas."', NULL, NULL, NULL, 31);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El KDS – El Fin del Caos en la Cocina', 'El KDS de INVU sincroniza pedidos en tiempo real, con alertas de comanda, reportes de tiempos y organización visual de órdenes. En cualquier restaurante latinoamericano, el caos en cocina es el principal generador de errores y demoras. El KDS elimina las comandas de papel, organiza la preparación y reduce los tiempos de espera. El vendedor debe mostrar que el KDS no es un lujo; es una necesidad para cualquier negocio de alimentos.', '"El caos en cocina se acaba con INVU KDS. Los pedidos llegan organizados, con alertas claras y tiempos medidos. Tu cocina sabe exactamente qué preparar, en qué orden y en cuánto tiempo. Menos errores, más rapidez, clientes felices. El flujo de pedidos deja de ser un problema y se convierte en tu ventaja. Dile adiós a las comandas de papel perdidas."', NULL, NULL, NULL, 32);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Datos en Tiempo Real – El Control en la Palma de la Mano', 'INVU Reportes permite acceder a ventas, movimientos y números clave en tiempo real desde cualquier parte del mundo, con IA integrada para agilizar el análisis. El dueño del negocio latinoamericano, que muchas veces no puede estar en todos sus locales, necesita este control remoto. El vendedor debe comunicar que INVU libera al dueño de la obligación de estar presente para saber qué está pasando.', '"Tu negocio no debería depender de que estés presente. Con INVU Reportes, ves tus ventas, movimientos y números clave en tiempo real desde cualquier lugar. Sin llamadas, sin esperar cierres, sin suposiciones. El control está donde estés tú. Puedes estar de viaje o en casa y saber exactamente cómo va tu operación."', NULL, NULL, NULL, 33);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Inventario que se Controla Solo', 'El inventario de INVU se actualiza automáticamente con cada venta, compra o ajuste. El sistema notifica cuándo hay que reabastecer y ayuda a hacer compras inteligentes. En Latinoamérica, donde las mermas y el desperdicio son fugas de dinero comunes, un inventario automático es una herramienta de rentabilidad. El vendedor debe mostrar que INVU convierte el inventario en un aliado, no en un dolor de cabeza.', '"Con INVU, tu inventario se controla solo. Cada venta lo actualiza, cada compra lo ajusta, y el sistema te avisa cuándo tienes que reabastecer. Nada de pérdidas por vencimiento, nada de quedarte sin lo que más vendes. Menos caos en el inventario, más control en tu negocio. Deja de comprar por intuición y empieza a comprar con datos."', NULL, NULL, NULL, 34);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Los Kioskos que Venden Mientras Tú Descansas', 'Los kioskos de autoservicio de INVU permiten a los clientes ordenar directamente sin esperas, con pedidos rápidos y total precisión. El cliente arma su pedido, paga, y el sistema lo envía directo a producción. En un mercado latinoamericano donde las filas largas pueden ahuyentar clientes, el autoservicio es una ventaja competitiva. El vendedor debe mostrar que los kioskos no solo venden; venden las 24 horas sin necesidad de personal adicional.', '"Imagina que tus clientes pueden pedir sin esperar, sin filas, sin errores. Los kioskos de INVU venden por ti las 24 horas. El cliente arma su pedido, paga, y el sistema lo envía directo a producción. Tú ganas en eficiencia, ellos ganan en rapidez. Es como tener un vendedor extra que nunca se cansa."', NULL, NULL, NULL, 35);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Ecommerce Integrado – El Canal Digital sin Comisiones', 'El ecommerce de INVU integra las ventas digitales directamente al sistema POS, con pedidos que entran limpios, inventario sincronizado y control total. Las ventas online no son un mundo aparte; se integran con el resto de la operación. Y lo mejor: el ecommerce propio de INVU no cobra comisiones. El vendedor debe comunicar que INVU permite vender por internet sin ceder el 25-30% a Rappi o PedidosYa.', '"Con INVU, tu ecommerce no es un mundo aparte. Los pedidos online entran directo al sistema, el inventario se actualiza solo, y toda la operación está sincronizada. Menos errores, menos reprocesos, más control. Un solo sistema para todo tu negocio. Y tu tienda online no paga comisiones: el 100% de la venta es para ti."', NULL, NULL, NULL, 36);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Wallet Digital – La Fidelización que el Cliente Siente', 'INVU Loyalty incluye tarjetas perforadas digitales y wallet, donde cada visita suma, cada compra deja huella y cada cliente siente que vale la pena regresar. El sistema de fidelización está integrado al POS; no es una herramienta separada. Cada compra suma puntos automáticamente. En Latinoamérica, donde la lealtad del cliente es clave para la sostenibilidad del negocio, esta herramienta es esencial.', '"Los buenos clientes siempre vuelven con INVU. El sistema de fidelización integra tarjetas perforadas y wallet digital: cada compra suma, el cliente ve su saldo en su celular, y tú ves cómo aumenta la recurrencia. El cliente gana, el negocio también. No pierdas más clientes que compran una vez y no regresan."', NULL, NULL, NULL, 37);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Facturación Electrónica que No Duele', 'INVU genera facturación electrónica automática, cumpliendo con requisitos legales y manteniendo la información conectada con ventas, inventarios y reportes. El comerciante no tiene que preocuparse por el proceso; el sistema lo hace automáticamente. En Latinoamérica, donde los requisitos fiscales varían por país, pero siempre son complejos, tener una facturación integrada es un alivio.', '"La facturación electrónica es necesaria, pero no tiene que ser un dolor de cabeza. INVU la genera automáticamente, la registra en ventas e inventarios, y cumple con todo lo que pide la ley. Tú sigues vendiendo, nosotros nos encargamos. No más errores, no más multas, no más procesos manuales."', NULL, NULL, NULL, 38);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Multiplataforma – El Hardware que ya Tienes Sirve', 'INVU funciona sin problemas en iOS, Android y Windows. El negocio no está atado a un tipo de hardware específico. Puede usar tablets, computadoras o dispositivos móviles según lo necesite la operación. En Latinoamérica, donde los presupuestos son ajustados, poder reutilizar el hardware existente es un ahorro significativo.', '"No te vamos a decir qué dispositivo comprar. INVU funciona en iOS, Android y Windows. Usa la tablet que ya tienes, la computadora que prefieras, o el dispositivo que elijas. La libertad de elegir es parte de nuestro valor. Y con tablets, tu personal puede tomar pedidos en cualquier lugar del local. No estás atado a un proveedor."', NULL, NULL, NULL, 39);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Costo de No Tener Integración', 'Los sistemas básicos parecen baratos, pero esconden costos: sistemas separados para delivery, ecommerce, inventario y fidelización; doble gestión de datos; pérdida de tiempo de los empleados; migración forzada al crecer. El vendedor debe mostrar que el costo real de una solución fragmentada es mayor que el costo de INVU a largo plazo.', '"Un sistema básico cuesta menos el primer año, pero al segundo año necesitas integración con delivery, al tercero ecommerce y fidelización. Cada una es un sistema separado con su costo. Al cuarto año, migras y pagas dos veces por todo. INVU, con su ecosistema integrado, evita estos costos. Invierte una vez, crece sin límites."', NULL, NULL, NULL, 40);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El ROI en el Contexto Latinoamericano', 'Un sistema POS básico en Latinoamérica tiene una vida útil de 2 a 3 años antes de volverse obsoleto. INVU está diseñado para crecer con el negocio, extendiendo su vida útil a más de 10 años sin necesidad de migrar. El retorno de inversión se produce a través del ahorro de tiempo, reducción de errores, incremento en ventas y control financiero.', '"Un sistema básico te dura 2-3 años. INVU te dura 10 años o más porque crece contigo. El ROI se calcula en ahorro de tiempo, reducción de errores, incremento en ventas y control financiero. Si INVU te ayuda a reducir mermas en un 2%, eso son S/1,000 mensuales de ahorro en un restaurante de S/50,000. La inversión se paga sola."', NULL, NULL, NULL, 41);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'Las Preguntas de Diagnóstico para LATAM', 'El vendedor debe hacer preguntas de diagnóstico adaptadas al contexto latinoamericano: número de locales y países, sistemas actuales, presencia en delivery y ecommerce, volumen de ventas, área de producción, planes de autoservicio, presupuesto, desafíos operativos, y comparación con otras marcas. Estas preguntas revelan el dolor real y permiten dimensionar la solución.', 'En una reunión con un dueño de restaurante en Bogotá, el vendedor pregunta: "¿Cuántos locales tienes y en qué ciudades? ¿Qué sistema usas hoy? ¿Manejas delivery propio o solo apps? ¿Tienes ecommerce? ¿Qué tan importante es para ti la fidelización?" Con las respuestas, el vendedor sabe que el cliente necesita integración de delivery y ecommerce, y que la fidelización es clave. El diagnóstico guía toda la conversación.', NULL, NULL, NULL, 42);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'La Comparación con Datos en el Mercado Regional', 'El vendedor debe comparar INVU con las alternativas del mercado regional, pero con datos concretos. Explicar qué ofrecen los sistemas básicos, dónde fallan y por qué INVU es superior en integración, flexibilidad, soporte y costo a largo plazo. La comparación debe basarse en números, no en opiniones.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene."', NULL, NULL, NULL, 43);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-1-invu', 'Framework Gravity INVU', 'El Framework Gravity Aplicado a LATAM', 'El Framework Gravity en el contexto latinoamericano se basa en 5 pasos: Diagnóstico (escuchar y entender la realidad del cliente), Educación (explicar la lógica del ecosistema integrado), Comparación (con datos concretos del mercado regional), Construcción de Valor (cuantificar beneficios), y Cierre (avanzar el proceso con confianza). Un cierre exitoso en LATAM se basa en la confianza y en haber demostrado que INVU entiende la realidad del cliente.', 'Un vendedor en Chile aplica Gravity: Diagnostica que el cliente tiene 3 locales y paga PSE externo. Educa sobre la FE nativa de INVU. Compara: "Tu costo actual es S/1,110/mes; con INVU es S/1,862/mes, pero incluye centralización y fidelización." Construye valor: "Si reduces mermas en un 2%, ahorras S/2,400/mes." Cierra: "¿Qué información necesitas para empezar la implementación?" El cliente confía y avanza.', NULL, NULL, NULL, 44);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Uso de WhatsApp para Avanzar la Venta', 'En Latinoamérica, WhatsApp es el canal de comunicación preferido. El vendedor debe ser breve, educativo y dejar una pregunta de avance. El objetivo no es cerrar en WhatsApp, sino avanzar a una llamada o reunión. El mensaje debe conectar con el dolor del cliente y ofrecer valor inmediato.', '"Hola [nombre], vi tu consulta sobre INVU. Entendemos que cada negocio en Latinoamérica tiene sus propias necesidades. ¿Me puedes contar cuántos locales tienes y qué sistema usas hoy? Con eso te comparto casos de éxito de negocios similares al tuyo en tu país." El cliente responde y el vendedor agenda una llamada. El WhatsApp es la puerta de entrada.', NULL, NULL, NULL, 1);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Llamada de 20 Minutos que Cierra', 'En una llamada de ventas en Latinoamérica, el vendedor debe controlar el ritmo: 5 minutos de diagnóstico, 5 de educación, 5 de comparación, 5 de construcción de valor, y cerrar con una pregunta de avance. La llamada no es una presentación de producto; es una solución de problemas. El objetivo es terminar con una reunión agendada o una decisión de compra.', 'Un vendedor llama a un dueño de restaurante en Lima. En 5 minutos, diagnostica: 2 locales, sistema básico, paga Nubefact. En 5 minutos, educa sobre FE nativa. En 5 minutos, compara: S/450 vs S/350. En 5 minutos, construye valor: ahorro de mermas y comisiones. Cierra: "¿Qué día te acomoda para la demo?" El cliente agenda. La llamada de 20 minutos avanza la venta.', NULL, NULL, NULL, 2);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Demo Presencial que Conecta con el Espacio del Cliente', 'En una reunión presencial en Latinoamérica, el vendedor debe llevar una demostración física del sistema, preferiblemente en el equipo del cliente. La demo no es un recorrido por todas las funcionalidades; es una conexión con el espacio del cliente. Se muestra cómo INVU resolvería los dolores específicos identificados en el diagnóstico. Se invita al cliente a tocar el sistema y hacer preguntas.', 'Un vendedor visita un restaurante en Bogotá. Lleva una tablet con INVU instalado. No hace una demo genérica; muestra cómo centralizaría los 2 locales del cliente, cómo el KDS organizaría la cocina, cómo el QR agilizaría los pedidos en mesa. El cliente toca la tablet, ve su propio menú cargado, y visualiza su operación con INVU. La demo termina con una cotización y un plan de implementación.', NULL, NULL, NULL, 3);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Caso del Restaurante con Delivery y Ecommerce', 'Un restaurante con 2 locales, facturación de S/150,000, delivery por apps y ecommerce desconectado del sistema, es un cliente ideal para INVU. El vendedor debe mostrar que INVU integra todo: POS, inventario, delivery, ecommerce y fidelización en una sola plataforma. El argumento es que el costo de INVU es menor que el costo de mantener sistemas separados y que las herramientas de INVU generarán ingresos adicionales que cubrirán la inversión.', 'El vendedor dice: "Con INVU, delivery y ecommerce se integran automáticamente. Los pedidos entran solos, el inventario se actualiza sin intervención, y tú tienes datos en tiempo real desde tu celular. El ahorro de tiempo y la reducción de errores justifican la inversión. Te propongo que hagamos una demostración enfocada en cómo integrarías delivery, ecommerce y tus 2 locales."', NULL, NULL, NULL, 4);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Manejo de la Objeción "Es Caro para Mi Tamaño"', 'El cliente que dice "es caro para mi tamaño de negocio" está comparando el precio de INVU con su facturación actual, sin ver el valor a largo plazo. El vendedor debe validar la preocupación, educar sobre la escalabilidad de INVU, comparar con el costo de sistemas separados, construir valor mostrando el ahorro en tiempo y el incremento en ventas, y cerrar con una pregunta de avance.', '"Entiendo que el presupuesto es importante. INVU es escalable: empiezas con lo que necesitas hoy: POS e inventario. Cuando crezcas, activas delivery, ecommerce, fidelización. No pagas por lo que no usas. Un sistema simple te va a costar menos ahora, pero te va a dar problemas de integración. Cuando necesites delivery o ecommerce, vas a tener que pagar sistemas separados. INVU ya los tiene integrados."', NULL, NULL, NULL, 5);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Manejo de la Objeción "Lo Voy a Pensar"', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El vendedor debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, construir valor ofreciendo una demo sin compromiso, y cerrar con una pregunta de avance para agendar la reunión.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener integración es mayor que el costo de implementarla. Cada mes sin integración es un mes de doble trabajo, inventario desactualizado y oportunidades perdidas. Pensarlo cuesta tiempo y dinero. No te pido que decidas hoy. Te pido que le des la oportunidad a INVU de demostrarte su valor en una reunión."


# PÍLDORAS DE CONOCIMIENTO - INVU POS HUNTERS', NULL, NULL, NULL, 6);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Rol del Hunter – Cazador, No Esperador', 'El Hunter no espera leads; sale a la calle a identificar negocios, contactar tomadores de decisión, presentar el valor de INVU y cerrar ventas. El Hunter es un cazador de oportunidades que construye su propio mercado. Su ingreso depende directamente de su esfuerzo: 15 visitas/semana, 10 reuniones con decisores, 5 demos/mes, 2-3 cierres/mes. El que no visita, no vende.', 'Un Hunter inicia su semana con una agenda de 15 visitas a restaurantes. No espera que el teléfono suene; sale a la calle, entra a los locales, identifica al dueño o gerente, y hace su pitch. En la primera semana, logra 5 reuniones. En la segunda, 3 demos. En la tercera, 2 cierres. Su ingreso: S/4,298. El Hunter que espera, no cobra. El que caza, triunfa.', NULL, NULL, NULL, 7);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Pitch de 30 Segundos que Abre Puertas', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?". El pitch debe memorizarse y adaptarse al contexto del cliente.', 'Un Hunter entra a un restaurante y dice: "INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable." El dueño, que ha estado batallando con su facturación electrónica, responde: "¿Cómo lo vemos?" El Hunter ya tiene la reunión.', NULL, NULL, NULL, 8);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Las 7 Preguntas del Hunter – El Mapa del Tesoro', 'El Hunter tiene 7 preguntas que revelan la calificación del cliente, sus dolores y los módulos que necesita. Sin estas preguntas, el Hunter está navegando sin mapa. Las preguntas cubren: facturación y sedes, sistema actual y dolor, facturación electrónica, recetas costeadas, número de cajas, delivery y ecommerce, y tomador de decisión y timeline.', 'En una primera reunión, el Hunter hace las 7 preguntas en 5 minutos. Descubre que el cliente tiene 3 sedes, paga Nubefact aparte, no tiene recetas costeadas, y quiere implementar QR y fidelización. El Hunter sabe exactamente qué cotizar: INVU Central + 3 licencias Sucursal + QR + Loyalty. El diagnóstico es el mapa; el cierre es el tesoro.', NULL, NULL, NULL, 9);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Facturación Electrónica Nativa – El Ahorro que el Cliente No Ve', 'El 70% de los restaurantes en Perú paga aparte por su facturación electrónica (S/89-149/mes). INVU incluye FE nativa sin límite de documentos. El Hunter debe mostrar que el costo de la competencia incluye un PSE externo que INVU ya tiene integrado. Cuando el cliente compara precios, el Hunter debe sumar ese costo oculto para mostrar el ahorro real.', 'Un cliente dice: "El POS X es más barato que INVU." El Hunter responde: "¿X incluye facturación electrónica nativa o pagas aparte a Nubefact o Efact?" El cliente admite que paga S/120/mes por Nubefact. El Hunter suma: "Entonces X te cuesta S/250 + S/120 + S/80 de soporte = S/450/mes. INVU es S/350/mes todo incluido. Termina siendo más barato." El cliente se queda pensando.', NULL, NULL, NULL, 10);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Llave en Mano – La Implementación que Diferencia', 'INVU no entrega un software para que el cliente lo configure; lo deja operando. Configuración completa, carga de menú con recetas, instalación de equipos, capacitación y go live acompañado. La competencia vende licencias y deja solo al cliente. El Hunter debe comunicar que INVU no es un software; es una operación lista para facturar.', '"La competencia te vende licencias y te deja solo. INVU te deja el restaurante operando desde el día uno. Nosotros configuramos, cargamos tu menú con recetas y costos, instalamos equipos, capacitamos a tu personal y estamos contigo el día del arranque. No pagas por un software, pagas por una operación lista para facturar." El cliente, que no tiene tiempo para configurar sistemas, valora el servicio.', NULL, NULL, NULL, 11);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Onboarding Consultivo – Costear para Ganar', 'INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación rentable: menú con recetas costeadas, materia prima, proveedores, márgenes reales por plato. Muchos dueños operan a ciegas: no saben cuánto ganan por plato, no controlan mermas. El onboarding consultivo transforma al vendedor en un asesor de confianza.', '"No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca ha visto el margen real de sus platos, percibe a INVU como un socio.', NULL, NULL, NULL, 12);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Soporte Local 24/7 – El Seguro de Continuidad', 'INVU tiene equipo de soporte en Perú, con WhatsApp directo a un humano, soporte remoto y en sitio. La competencia tiene tickets de 24-48 horas y soporte desde otro país. Cuando el sistema falla un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. El Hunter debe vender esto como tranquilidad operativa.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El Hunter responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma." El cliente se siente seguro.', NULL, NULL, NULL, 13);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Ecosistema Móvil Nativo – El Negocio en el Bolsillo', 'INVU ofrece tres apps nativas: POS para operar, Reports para medir desde cualquier lugar, y Supply para inventario y compras desde el móvil. La competencia encadena al usuario a una sola pantalla fija. El Hunter debe comunicar que INVU libera al dueño de la obligación de estar presente para controlar su negocio.', '"Con INVU, tu negocio vive donde vos estés. Operás desde cualquier dispositivo con INVU POS, medís tus ventas y movimientos con INVU Reports desde tu celular, y gestionás compras e inventario con INVU Supply. No estás encadenado a una caja fija. Puedes estar en casa o de viaje y saber exactamente cómo va tu operación."', NULL, NULL, NULL, 14);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Ecosistema Integrado sin Comisiones – El 100% es para Ti', 'INVU integra POS, KDS, inventario, QR, kioskos, loyalty y e-commerce en una sola plataforma, con e-commerce propio sin comisiones por venta. La competencia cobra comisiones de 25-30% por delivery. El Hunter debe mostrar que INVU permite vender sin ceder margen a terceros, lo que multiplica la rentabilidad del cliente.', '"No necesitas cinco sistemas diferentes. INVU integra POS, inventario, facturación, QR, kioskos, loyalty y e-commerce en una sola plataforma. Y tu tienda online no paga comisiones: el 100% de la venta es para ti. Un solo sistema, un solo costo, cero comisiones. Lo que antes perdías en Rappi, ahora lo ganas."', NULL, NULL, NULL, 15);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Escalera Base – Protección para el Hunter', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258. No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', NULL, NULL, NULL, 16);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Comisiones desde la Venta 4 – El Ingreso sin Techo', 'Desde la cuarta venta, el Hunter gana 10% sobre setup facturado y pagado, 3% MRR mensual sobre licencias activas durante 12 meses, y 3% sobre hardware. Las comisiones se suman a la base, no la reemplazan. El ingreso del Hunter no tiene techo: cada venta adicional es puro ingreso incremental.', 'Un Hunter cierra 7 ventas en un mes. Base: S/2,958. Comisiones de setup de las ventas 4 a 7: 10% de S/700 = S/980. Bono Top Performer: S/1,020. Cola MRR de las licencias activas: S/504. Ingreso total: S/5,462. Cada venta adicional es puro ingreso extra. No hay techo.', NULL, NULL, NULL, 17);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El MRR – Ingresos Pasivos que se Construyen', 'El 3% MRR se paga mensualmente durante 12 meses sobre las licencias activas de cada cliente que el Hunter trajo. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional.', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin esfuerzo adicional.', NULL, NULL, NULL, 18);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Los Bonos – Gasolina Extra para el Esfuerzo', 'Bonos escalonados: Bono de Inicio S/408 (3 ventas en primer mes), Ejecutivo Ideal S/850 (5 ventas/mes), Top Performer S/1,020 (7 ventas/mes), Bono Trimestral S/3,400 (promedio 10 ventas/mes). Los bonos transforman un buen mes en un mes excepcional y recompensan la consistencia.', 'Un Hunter tiene un mes con 7 ventas. Base: S/2,958. Comisiones: S/980. Bono: S/1,020. Total: S/4,958. Si mantiene 10 ventas/mes en el trimestre, gana S/3,400 adicionales. La diferencia entre 5 y 7 ventas es S/170 de bono extra; entre 7 y 10, el bono trimestral de S/3,400. El esfuerzo adicional se paga solo.', NULL, NULL, NULL, 19);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', '"Venta Grande Vale por Tres" – Apunta a lo Grande', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (ej. una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas.', NULL, NULL, NULL, 20);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', NULL, NULL, NULL, 21);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Ritmo del Hunter Ganador', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base S/2,958 + comisiones S/490 + bono S/850 + MRR S/252 = S/4,550. El esfuerzo se traduce en dinero.', NULL, NULL, NULL, 22);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Comparación con Números – El Argumento del Ahorro', 'El Hunter debe comparar INVU con las alternativas del mercado peruano con datos concretos. Sumar el costo del PSE externo, el soporte aparte y las horas de configuración que la competencia no incluye. Mostrar que INVU (S/350/mes todo incluido) es más barato que la competencia (S/450/mes con PSE y soporte). La diferencia de S/100 es el 0.2% de la facturación de un restaurante de S/50,000.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene. Esa diferencia de S/100 al mes es el 0.2% de tu facturación."', NULL, NULL, NULL, 23);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Objeción "Es Caro" – El Protocolo Gravity', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity para "es caro" tiene 5 pasos: Validar (entiendo que el precio es importante), Diagnosticar (¿qué te parece caro exactamente?), Reencuadrar (cuando sumas el PSE, el costo real es mayor), Micro-cierre (¿te parece si hacemos el cálculo con tus números?), y Cierre (¿qué día te acomoda para la demo?).', 'Cliente: "Es caro."  
Hunter:  
"Entiendo que el precio es una consideración importante."  
"¿Qué es lo que te parece caro exactamente, el setup o las licencias mensuales?"  
"Cuando sumas lo que pagas por Nubefact (S/120/mes), soporte (S/80/mes) y sistemas separados, el costo real de la competencia es S/450/mes. INVU es S/350/mes todo incluido."  
"¿Te parece si hacemos el cálculo con tus números actuales?"  
"¿Qué día te acomoda para la demo?"', NULL, NULL, NULL, 24);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Objeción "Ya Tengo un POS" – Diagnosticar el Dolor', 'El cliente que dice "ya tengo un POS" no está cerrado; está diciendo que no ve razón para cambiar. El Hunter debe diagnosticar qué le falta a su sistema actual. Preguntas: "¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real?" Si no tiene esas funcionalidades, INVU es una mejora.', '"Me alegra que tengas un sistema. ¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. No se trata de cambiar por cambiar. Se trata de tener una operación rentable."', NULL, NULL, NULL, 25);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Objeción "Lo Voy a Pensar" – El Costo de la Postergación', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El Hunter debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, y cerrar ofreciendo una demo sin compromiso.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos."', NULL, NULL, NULL, 26);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Setup – Inversión, No Gasto', 'El setup de INVU es un desembolso inicial que muchos clientes ven como un gasto. El Hunter debe reencuadrarlo como una inversión que ahorra meses de operación rota. La competencia no cobra setup porque no hace nada: da el software y el cliente lo configura. INVU cobra setup porque deja el restaurante operando desde el día uno.', '"Entiendo que el setup es un desembolso inicial importante. Ese setup lo pagás una vez y te ahorra meses de operación rota. Además te lo podemos plantear como facturación anual con mejor precio. La competencia no cobra setup porque no hace nada: te dan el software y tú lo configuras. INVU te deja el restaurante operando desde el día uno. El setup es inversión, no gasto."', NULL, NULL, NULL, 27);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al Hunter profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al Hunter con datos reales.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', NULL, NULL, NULL, 28);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Caso del Restaurante con Facturación Externa y Múltiples Sedes', 'Un cliente con 3 sedes que paga Nubefact aparte y no tiene control centralizado es el cliente ideal para INVU. El Hunter debe mostrar que el costo actual (S/1,110/mes) es solo un poco menor que INVU (S/1,862/mes), pero que INVU incluye centralización, FE nativa, KDS y Loyalty. El ahorro en mermas (2% = S/2,400/mes) y comisiones de delivery cubren la diferencia.', '"Entiendo que el costo de INVU es mayor que lo que pagas hoy. Hoy pagas S/1,110 mensuales: S/750 por los 3 POS y S/360 por Nubefact. Con INVU, el costo mensual es S/1,862, que incluye centralización, FE nativa, KDS y Loyalty. La diferencia es S/752, que es el 0.6% de tu facturación mensual. Pero lo que no estás viendo es lo que te cuesta no tener centralización: precios desactualizados, inventario que no cuadra, mermas sin control. Si reducimos tus mermas en un 2%, son S/2,400 mensuales de ahorro. La inversión se paga sola."', NULL, NULL, NULL, 29);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Los Errores que Matan la Venta', 'Hay 6 errores comunes que el Hunter debe evitar: Hablar de precio antes de diagnosticar; hacer una demo genérica sin enfocarse en el dolor; no sumar los costos ocultos de la competencia; no comparar con la competencia local; no cerrar con una pregunta de avance; hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza".', 'Un cliente pregunta: "¿Cuánto cuesta?"  
El Hunter novato responde: "S/350/mes." El cliente dice: "Es caro." Se va.  
El Hunter experto responde: "El costo depende de tus necesidades. Permíteme hacerte algunas preguntas para entender tu operación y darte una cotización precisa. ¿Cuántas sedes tienes? ¿Qué sistema usas hoy?" El cliente se queda, responde, y el Hunter construye valor antes de dar el precio.', NULL, NULL, NULL, 30);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Los Niveles de Dominio – De Básico a Gravedad Cero', 'El Hunter pasa por 4 niveles: Básico (explica el producto sin conectar beneficios), Medio (conecta beneficios y diagnostica), Alto (justifica el precio y maneja objeciones con autoridad), y Gravedad Cero (controla la conversación y cierra con autoridad, sin descuentos). El objetivo es llegar a Gravedad Cero: ser un asesor estratégico del restaurantero, no un vendedor más.', 'Básico: "INVU tiene facturación electrónica nativa."  
Medio: "INVU incluye FE nativa, así que te ahorras S/120/mes en Nubefact."  
Alto: "Cuando sumas el PSE, soporte y sistemas separados, la competencia te cuesta S/450/mes. INVU es S/350/mes todo incluido. Y el onboarding consultivo te da visibilidad de márgenes que nunca tuviste."  
Gravedad Cero: El cliente dice: "¿Qué necesito firmar?" El Hunter ya no vende; el cliente compra porque confía en él.


# PÍLDORAS DE CONOCIMIENTO - PROGRAMA DE REFERIDOS INVU POS PERÚ', NULL, NULL, NULL, 31);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Programa de Referidos – La Puerta de Entrada sin Esfuerzo', 'El Programa de Referidos INVU está diseñado para que cualquier persona con contactos en la industria gastronómica pueda monetizar su red sin necesidad de ser vendedor. El referidor no vende, no hace demos, no cotiza y no implementa. Su única función es abrir la puerta: identificar un negocio que califique, contactar al tomador de decisión, presentar a INVU como el socio recomendado, y asegurar una reunión. El equipo de INVU hace el resto. Es el programa de referidos más simple y accesible del mercado peruano.', 'Un cliente satisfecho de INVU, dueño de un restaurante, conoce a otro restaurador que tiene problemas con su facturación electrónica. El cliente le dice: "Oye, INVU me cambió la vida. Te recomiendo que los conozcas. ¿Quieres que los contacte para que te hagan una demo sin compromiso?" El restaurador acepta. El cliente envía un correo a INVU con los datos de contacto. El equipo de INVU agenda la reunión, cierra la venta, y el cliente referidor cobra S/1,000 sin haber hecho nada más que abrir la puerta.', NULL, NULL, NULL, 32);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Comisiones Fijas – Transparencia Total', 'El referidor cobra una comisión fija según el tamaño del negocio: S/500 para negocio pequeño (1-2 sedes), S/1,000 para negocio en crecimiento (3-5 sedes), S/1,500 para cuenta consolidada (más de 5 sedes). No hay porcentajes variables, no hay condiciones de permanencia, no hay pagos fraccionados. El referidor sabe exactamente cuánto va a ganar desde el momento en que identifica el negocio. Esta transparencia es un diferenciador clave frente a otros programas de referidos.', 'Un proveedor de insumos conoce a una cadena de 10 restaurantes. Sabe que si refiere ese negocio a INVU, cobrará S/1,500 cuando el cliente firme y pague su primera factura. No tiene que calcular porcentajes ni preocuparse por si el cliente se mantiene 6 o 12 meses. El cálculo es simple: S/1,500. Esta claridad lo motiva a hacer la referencia.', NULL, NULL, NULL, 33);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Protección de Oportunidad – 90 Días de Exclusividad', 'El referidor que registra primero un negocio queda como propietario de esa oportunidad durante 90 días. Si el negocio avanza y cierra dentro de ese plazo, la comisión es para el referidor que lo registró. Esto elimina la competencia desleal y protege el esfuerzo del referidor. Es la garantía de que su trabajo no será aprovechado por otro.', 'Un referidor identifica un restaurante de 3 sedes, contacta al dueño, y registra la oportunidad en INVU mediante correo a lizeth@invupos.com. Dos semanas después, otro referidor intenta registrar el mismo negocio. INVU verifica que el primero ya lo tiene registrado y protege la oportunidad del referidor original. Este último tiene la tranquilidad de que su comisión está asegurada si el negocio cierra dentro de los 90 días.', NULL, NULL, NULL, 34);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Proceso de 3 Pasos – Simple y Sin Complicaciones', 'El programa de referidos tiene un proceso simple de tres pasos: Preséntanos (contacta al decisor y presenta a INVU), Facilita los datos (envía contacto e información clave a INVU), Asegura la cita (deja la reunión agendada). De ahí en adelante, INVU toma el control. El referidor no tiene que hacer demos, ni cotizaciones, ni seguimiento comercial. El proceso es tan simple que cualquier persona, sin importar su experiencia en ventas, puede participar.', 'Un contador con clientes restauranteros quiere referirlos a INVU. No sabe cómo hacer una demo ni cómo manejar objeciones técnicas. Pero el proceso de 3 pasos es simple: 1) Contacta a su cliente dueño de un restaurante y le dice que INVU es el sistema que recomienda. 2) Envía un correo a lizeth@invupos.com con los datos del cliente. 3) Agenda una reunión entre el cliente y el equipo de INVU. El contador no necesita saber nada más; INVU hace el resto.', NULL, NULL, NULL, 35);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Perfil del Cliente Ideal para Referir', 'El referidor debe enfocar sus esfuerzos en negocios que califiquen: restaurantes, bares, cafeterías, franquicias, cadenas de comida, o comercios gastronómicos que facturen al menos S/30,000 mensuales. Si el negocio no cumple con este perfil, probablemente no sea un buen cliente para INVU y el referidor perderá tiempo. Identificar el perfil correcto es el primer paso para maximizar la efectividad del referidor.', 'Un referidor conoce a un amigo que tiene una pequeña cafetería que factura S/10,000 mensuales. Sabe que este negocio no califica para INVU, así que no pierde tiempo refiriéndolo. En cambio, enfoca sus esfuerzos en otro contacto: un dueño de una cadena de 5 restaurantes que factura S/150,000 mensuales. Este sí califica y el referidor puede ganar S/1,000 por la referencia.', NULL, NULL, NULL, 36);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'Las 7 Preguntas del Referidor – Calificar Antes de Referir', 'El referidor debe hacer 7 preguntas de diagnóstico antes de referir un negocio: sector gastronómico o comercial, número de sedes, facturación mensual, sistema actual y dolor, tomador de decisión, problemas específicos (facturación, inventario, centralización, retención de clientes), y planes de crecimiento. Estas preguntas aseguran que el negocio califica y que INVU tiene una oportunidad real de cerrar la venta.', 'Un referidor contacta a un conocido dueño de un restaurante. En lugar de referirlo inmediatamente, hace las 7 preguntas: "¿Cuántas sedes tienes? ¿Qué sistema usas hoy? ¿Cómo manejas la facturación electrónica? ¿Tienes recetas costeadas? ¿Quién toma las decisiones? ¿Tienes planes de abrir más locales?" Al obtener las respuestas, el referidor confirma que el negocio califica y que el dolor principal es la falta de centralización. Ahora puede presentar a INVU de manera más efectiva, enfocándose en ese dolor.', NULL, NULL, NULL, 37);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Mensaje que Abre Puertas – Presentación Sin Presión', 'El referidor debe presentar a INVU de manera atractiva pero sin presión, conectando con el dolor del negocio. Un buen mensaje es: "Conozco a INVU POS, es el sistema que usan más de 5,000 restaurantes en Latam. Son especialistas en restaurantes, incluyen facturación electrónica nativa y te dejan el negocio operando desde el día uno. Creo que pueden ayudarte con [el dolor específico]. Te recomiendo que los conozcas." Esta presentación es breve, clara y enfocada en el beneficio.', 'Un referidor le dice a un dueño de restaurante: "Oye, sé que has tenido problemas con el inventario y la facturación electrónica en tus 3 locales. Te quiero recomendar INVU POS, el sistema que usamos en mi restaurante. Nos cambió la vida: incluimos facturación electrónica nativa sin pagar extra a Nubefact, centralizamos el inventario de los 2 locales, y vemos reportes en tiempo real desde el celular. ¿Quieres que los contacte para que te hagan una demo sin compromiso?" El dueño, que confía en el referidor, acepta.', NULL, NULL, NULL, 38);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Cierre del Referidor – Asegurar la Reunión', 'El cierre del referidor no es cerrar una venta; es asegurar una reunión. El referidor debe preguntar: "¿Te parece si los contacto para que te hagan una demo enfocada en tu negocio? No hay compromiso, solo conoces la solución. ¿Qué día te acomoda?" Cuando el referidor asegura la reunión, su trabajo está hecho. Luego registra la oportunidad en INVU y espera su comisión.', 'Un referidor ha presentado INVU a un colega restaurador. El colega muestra interés. El referidor cierra: "¿Qué te parece si les paso tu contacto para que te llamen y agenden una reunión? Ellos se encargan de todo. ¿Te parece bien? ¿Qué día te acomoda?" El colega dice: "El jueves a las 10am." El referidor envía el correo de registro a INVU y su comisión está protegida.', NULL, NULL, NULL, 39);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Registro Correcto – Protege tu Comisión', 'El referidor debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com, incluyendo: nombre del negocio, nombre y cargo del tomador de decisión, teléfono y correo de contacto, número de sedes, facturación aproximada, y sistema actual. Sin este registro, la comisión del referidor no está protegida. Lo que no está registrado, no existe.', 'Un referidor asegura una reunión con un dueño de restaurante, pero no envía el correo de registro. Dos semanas después, otro referidor registra el mismo negocio. El primero pierde la comisión porque no protegió su oportunidad. El segundo referidor, que sí registró, cobra S/1,000 cuando el negocio cierra. El referidor que no registró aprende la lección.', NULL, NULL, NULL, 40);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Valor del Esfuerzo vs. la Comisión', 'El referidor invierte entre 1 y 3 horas para identificar, contactar, presentar y registrar un negocio. Por ese esfuerzo, puede ganar S/500, S/1,000 o S/1,500. La tasa de retorno es de S/167 a S/500 por hora, muy superior al ingreso promedio en Perú. Si el referidor mantiene una red de contactos activa y refiere negocios regularmente, puede generar un ingreso complementario significativo con bajo esfuerzo.', 'Un contador refiere 1 negocio pequeño al mes (S/500). Son 3 horas de trabajo al mes. Ingreso anual: S/6,000. Si refiere 1 negocio en crecimiento al mes (S/1,000), son S/12,000 anuales. Si refiere 1 cuenta consolidada al mes (S/1,500), son S/18,000 anuales. Todo con 3 horas de trabajo al mes. El esfuerzo es mínimo; el retorno es alto.', NULL, NULL, NULL, 41);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Riesgo Cero para el Referidor', 'El referidor no asume ningún riesgo financiero. No invierte dinero, no firma contratos, no garantiza el pago del cliente. Su único riesgo es que el negocio referido no cierre dentro de los 90 días, lo que significaría que su esfuerzo de 1-3 horas no rinde fruto. Dado que INVU tiene un alto índice de cierre en negocios calificados, este riesgo es muy bajo. El referidor solo gana; nunca pierde.', 'Un referidor identifica un negocio potencial y lo registra. El negocio no cierra dentro de los 90 días por razones ajenas al referidor (el dueño decidió posponer la inversión). El referidor no pierde dinero; solo perdió 3 horas de su tiempo. Pero tiene otros contactos en su red y sigue refiriendo. Eventualmente, uno de sus referidos cierra y cobra su comisión. El riesgo es mínimo.', NULL, NULL, NULL, 42);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Comparación – Por qué INVU es Superior a Otros Programas', 'Otros programas de referidos tienen comisiones variables basadas en porcentaje (5-15%), condiciones de permanencia del cliente (6-12 meses), exigencia de participación en el proceso de venta, y sin protección de oportunidad. INVU ofrece comisiones fijas (S/500, S/1,000, S/1,500), sin condiciones de permanencia, sin exigencia de participación en ventas, y con protección de oportunidad por 90 días. El programa de INVU es más simple, más transparente y más rentable para el referidor.', 'Un referidor compara dos programas. En el programa X, la comisión es del 10% de la venta, pero el cliente debe permanecer 12 meses y el referidor debe ayudar en las demos. En INVU, la comisión es fija (S/1,000 para un negocio de 3 sedes), sin condiciones de permanencia, y el referidor solo abre la puerta. El referidor elige INVU porque es más simple y menos riesgoso.', NULL, NULL, NULL, 43);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Potencial de Ingresos Ilimitado', 'El referidor puede referir múltiples negocios y acumular comisiones sin límite. No hay tope de ingresos ni restricción de cantidad de referidos. Cuantos más negocios conecte, más comisiones acumula. Puede convertirlo en un ingreso recurrente si tiene una red de contactos activa en la industria gastronómica. El potencial de ingresos es ilimitado.', 'Un proveedor de insumos tiene una red de 50 clientes restauranteros. Refiere a 10 de ellos a INVU en un año. Si la mayoría son negocios de 3-5 sedes, gana S/1,000 por cada uno = S/10,000 anuales. Si algunos son cuentas consolidadas, gana S/1,500 por cada uno. El ingreso es significativo y el esfuerzo es compartido. El proveedor no tiene que vender; solo abrir la puerta.
```', NULL, NULL, NULL, 44);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Cliente Satisfecho como el Mejor Referidor', 'El cliente satisfecho de INVU es el mejor referidor porque tiene experiencia directa con el sistema y puede dar testimonio de su valor. Su recomendación tiene un peso enorme porque viene de alguien que ya confía en INVU. El programa de referidos convierte a los clientes satisfechos en una extensión del equipo de ventas, amplificando el alcance comercial de INVU sin costo adicional.', 'Un cliente de INVU con 2 locales recomienda el sistema a un colega restaurador. Le dice: "Nos cambió la vida: incluimos facturación electrónica nativa sin pagar extra a Nubefact, centralizamos el inventario de los 2 locales, y vemos reportes en tiempo real desde el celular. Además, el soporte es 24/7 en Perú." El colega confía en la recomendación y agenda una reunión con INVU. El cliente satisfecho cobra S/1,000 por la referencia.', NULL, NULL, NULL, 1);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "No Necesito Cambiar"', 'El referidor debe manejar la objeción del potencial cliente que dice "no necesito cambiar mi sistema". La respuesta es validar su postura, pero luego preguntar: "¿Tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados?" Si el cliente responde que no a estas preguntas, el referidor puede mostrar que INVU es una mejora, no solo un cambio.', 'Un referidor le dice a un restaurador: "Entiendo. Pero ¿tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? INVU hace todo eso en un solo sistema. Te recomiendo que al menos los conozcas, no pierdes nada." El restaurador, que paga Nubefact aparte y no centraliza su inventario, se queda pensando y acepta la reunión.', NULL, NULL, NULL, 2);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Es Caro"', 'El referidor debe manejar la objeción del potencial cliente que dice "es caro". La respuesta es validar su preocupación, pero luego mostrar que cuando se suman los costos de facturación electrónica aparte, soporte, y sistemas separados, INVU termina siendo más barato. Además, el control de inventario y la reducción de mermas pagan la inversión.', 'Un referidor le dice a un restaurador: "Yo pensé lo mismo, pero cuando sumas lo que pagas por facturación electrónica aparte, por soporte, y por sistemas separados, termina siendo más barato. Además, el control que te da en inventario y la reducción de mermas pagan la inversión. Vale la pena conocerlos." El restaurador, que no había sumado todos los costos, acepta la reunión.', NULL, NULL, NULL, 3);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Lo Voy a Pensar"', 'El referidor debe manejar la objeción del potencial cliente que dice "lo voy a pensar". La respuesta es validar que es normal, pero ofrecer una demo sin compromiso: "Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada." Esto quita presión y permite que el cliente avance en el proceso sin sentirse forzado.', 'Un referidor le dice a un restaurador: "Es normal. Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada. ¿Qué te parece?" El restaurador, que se sentía presionado a decidir, se relaja y acepta la demo.', NULL, NULL, NULL, 4);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Ya Tengo un Amigo que me Recomendó Otro Sistema"', 'El referidor debe manejar la objeción del potencial cliente que dice que ya tiene otra recomendación. La respuesta es no descalificar la otra opción, sino ofrecer una comparación informada: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada."', 'Un referidor le dice a un restaurador: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada. ¿Te parece?" El restaurador, que no quería cerrarse a una sola opción, acepta conocer a INVU.', NULL, NULL, NULL, 5);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción del Referidor "No Sé Vender"', 'El referidor que dice "no sé vender" debe recordar que no necesita vender. Solo necesita abrir la puerta y presentar a INVU. INVU es el que cierra. El único trabajo del referidor es conectar y asegurar la reunión. Eso lo puede hacer cualquier persona con contactos en la industria, sin importar su experiencia en ventas.', 'Un contador duda en referir a sus clientes porque cree que necesita saber vender. Pero luego recuerda: "No necesito vender. Solo necesito abrir la puerta y presentar a INVU. INVU es el que cierra. Mi único trabajo es conectar y asegurar la reunión." Con esta mentalidad, contacta a su primer cliente restaurantero y agenda una reunión con INVU.', NULL, NULL, NULL, 6);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Los Niveles de Dominio del Referidor', 'El referidor pasa por 4 niveles: Básico (identifica oportunidades pero no las registra, pierde comisiones), Medio (presenta y registra, protege su comisión), Alto (construye una red activa, genera flujo constante de comisiones), y Gravedad Cero (se convierte en partner estratégico, con ingresos recurrentes y reconocimiento de INVU). El objetivo es llegar a Gravedad Cero: ser un socio estratégico de INVU con una red amplia y confiable.', 'Básico: Conoce a un restaurador pero no lo refiere formalmente. Pierde la comisión.
Medio: Refiere a un restaurador, registra la oportunidad, y cobra S/1,000.
Alto: Refiere a 5 restauradores al año, todos registrados, ganando S/5,000 anuales.
Gravedad Cero: Tiene una red de 20 contactos en la industria, refiere 10 negocios al año, gana S/10,000+ anuales, e INVU lo reconoce como un aliado de crecimiento.', NULL, NULL, NULL, 7);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Registro en CRM – Lo que no se registra, no existe', 'El referidor debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com. Sin registro, no hay protección de oportunidad y no hay comisión. El registro es el paso que convierte el esfuerzo del referidor en dinero. No hay atajos.', 'Un referidor asegura una reunión pero se olvida de registrar. El negocio cierra, pero otro referidor había registrado la oportunidad antes. El primero pierde S/1,000. El segundo cobra. El primer referidor aprende la lección: lo que no se registra, no existe.', NULL, NULL, NULL, 8);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Bono Especial para Cuentas Consolidadas', 'Para cuentas consolidadas (más de 5 sedes), el referidor no solo cobra S/1,500, sino que tiene posibilidad de bono especial según el tamaño del negocio. Esto reconoce el valor de traer oportunidades de gran escala y incentiva al referidor a enfocarse en cadenas grandes.', 'Un referidor refiere una cadena de 15 restaurantes a INVU. Cobra S/1,500 de comisión base y además recibe un bono especial de S/500 por el tamaño del negocio. Total: S/2,000 por una sola referencia. El referidor se enfoca en buscar más cadenas grandes.', NULL, NULL, NULL, 9);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Valor de la Red de Contactos', 'La red de contactos del referidor es su activo más valioso. Cada contacto en la industria gastronómica es una oportunidad potencial de referido. El referidor debe cultivar su red, mantenerse en contacto con los dueños de restaurantes, y estar atento a las oportunidades. Una red amplia y activa es la clave para generar ingresos recurrentes.', 'Un proveedor de insumos tiene una lista de 100 clientes restauranteros. Cada mes, contacta a 5 de ellos para saber cómo va su negocio y si están considerando cambiar de sistema POS. Cuando encuentra a uno que está frustrado con su sistema actual, lo refiere a INVU. Su red de contactos es su máquina de generar ingresos.', NULL, NULL, NULL, 10);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Programa de Referidos como Extensión del Equipo de Ventas', 'El programa de referidos convierte a los referidores en una extensión del equipo de ventas de INVU, ampliando su alcance en el mercado peruano sin costo fijo. Los referidores abren puertas que el equipo comercial no podría abrir por sí mismo, aprovechando la confianza y las relaciones personales en la industria. Esto acelera el crecimiento de INVU y genera beneficios para todos.', 'El equipo de ventas de INVU no puede contactar a todos los restaurantes de Lima. Pero 100 referidores, cada uno con 10 contactos en la industria, pueden abrir 1,000 puertas. El programa de referidos multiplica el alcance comercial de INVU, generando más oportunidades de venta y más ingresos para los referidores.', NULL, NULL, NULL, 11);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Resultado Esperado – Una Red de Referidores Activos', 'El resultado esperado del programa de referidos es una red de referidores activos que generan un flujo constante de negocios calificados para el equipo comercial de INVU. Los referidores transforman su red de contactos en una fuente de ingresos adicionales, recomiendan a INVU con confianza, registran sus oportunidades correctamente, y cobran sus comisiones sin esfuerzo adicional. El programa de referidos se convierte en un motor de crecimiento para INVU y en una fuente de ingresos para los referidores.', 'Un año después del lanzamiento del programa, INVU tiene 200 referidores activos. Cada referidor refiere un promedio de 2 negocios al año. Son 400 oportunidades calificadas que llegan al equipo comercial. El equipo cierra el 40% de esas oportunidades: 160 nuevos clientes. Los referidores cobran sus comisiones. INVU crece. Todos ganan.


# PÍLDORAS DE CONOCIMIENTO - PROGRAMA PARTNERS INVU POS PERÚ', NULL, NULL, NULL, 12);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Partner – Un Socio Estratégico, No un Referidor', 'El Programa Partners es una evolución del programa de referidos. Mientras el referidor cobra una comisión fija (S/500, S/1,000, S/1,500), el Partner cobra el 8% del valor total del primer año del cliente (setup + 12 mensualidades), pagado en tres tramos. El Partner tiene un incentivo para traer clientes más grandes, porque su comisión crece proporcionalmente al tamaño del negocio. El referido es para contactos ocasionales; el Partner es para profesionales que quieren monetizar su red de contactos de manera recurrente.', 'Un contador refiere a un cliente de 1 sede: comisión S/532 (8% de S/6,650). Si el mismo contador refiere una cadena de 10 sedes: comisión S/6,057 (8% de S/75,708). El contador entiende que su red de contactos de clientes grandes vale mucho más. Se convierte en Partner y enfoca sus esfuerzos en las cuentas grandes.', NULL, NULL, NULL, 13);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El 8% del Valor del Primer Año – Cuanto más Grande, más Ganas', 'La comisión del Partner está directamente ligada al tamaño del negocio que refiere. No es una comisión fija; es el 8% del setup + 12 mensualidades del cliente. Un cliente de 1 sede genera S/532; un cliente de 3 sedes genera S/1,992; un cliente de 10 sedes genera S/6,057; una cuenta estratégica puede generar más de S/10,000. El Partner tiene incentivo para buscar los clientes más grandes y valiosos.', 'Un Partner tiene dos contactos: un restaurante de 1 sede y una cadena de 15 sedes. El primero le daría S/532; el segundo, con comisión preferente del 10%, le daría más de S/13,000. El Partner enfoca su tiempo en la cadena grande porque su esfuerzo se multiplica. La comisión sigue al valor del cliente.', NULL, NULL, NULL, 14);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Pago en Tres Tramos – Cobro Rápido, Sin Esperas', 'La comisión total se paga en tres tramos: 40% al primer pago del cliente (setup + 1era mensualidad), 30% a los 60 días, 30% a los 90 días. El Partner no tiene que esperar 6 o 12 meses para cobrar su comisión completa. El primer pago llega tan pronto como el cliente firma y paga su primera factura. Esto genera confianza, flujo de caja rápido, y motiva a seguir refiriendo negocios.', 'Un Partner refiere una cadena de 10 sedes. Valor año 1: S/75,708. Comisión 8%: S/6,057. El Partner cobra S/2,423 al primer pago del cliente (40%), S/1,817 a los 60 días (30%), y S/1,817 a los 90 días (30%). En 3 meses, el Partner ha cobrado toda su comisión, sin esperar 12 meses como en otros programas. Esto es un gran diferenciador.', NULL, NULL, NULL, 15);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Protección de Oportunidad por 90 Días – Tu Esfuerzo, tu Comisión', 'El Partner que registra primero un negocio queda como propietario de esa oportunidad durante 90 días. Si el negocio avanza y cierra dentro de ese plazo, la comisión es para el Partner que lo registró. Esto elimina la competencia desleal y protege el esfuerzo del Partner. La protección es la garantía de que su trabajo no será aprovechado por otro.', 'Un Partner registra una oportunidad de 5 sedes. Otro Partner intenta registrar el mismo negocio dos semanas después. INVU verifica que el primero ya lo tiene registrado y protege la oportunidad del Partner original. El primer Partner tiene la tranquilidad de que su comisión de S/1,992 está asegurada si el negocio cierra dentro de los 90 días.', NULL, NULL, NULL, 16);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Bono Extraordinario de S/2,000 – La Recompensa por el Volumen', 'Si el Partner cierra más de 20 sucursales en 3 meses (de uno o varios clientes), gana un bono adicional de S/2,000. Esto incentiva al Partner a no limitarse a uno o dos clientes pequeños, sino a buscar múltiples clientes o cuentas grandes. El bono es por volumen y se suma a las comisiones ya generadas. Es un incentivo extra para escalar.', 'Un Partner cierra en un trimestre: una cadena de 10 sedes, otra de 8 sedes, y una de 5 sedes. Total: 23 sucursales. Gana comisiones: S/6,057 + S/4,846 + S/1,992 = S/12,895. Además, gana el bono de S/2,000. Ingreso trimestral: S/14,895. El bono transforma un buen trimestre en un trimestre excepcional.', NULL, NULL, NULL, 17);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Comisión Preferente del 10% para Cuentas Estratégicas', 'Para cuentas de alto volumen (cadenas de 15+ sucursales), INVU ofrece una comisión preferente de hasta el 10%, acordada por escrito antes del cierre. Las cuentas estratégicas requieren más esfuerzo en la prospección y el contacto inicial. El Partner merece una compensación adicional por traer oportunidades de esta escala. Esto reconoce el valor de traer cuentas grandes.', 'Un Partner identifica una cadena de 20 restaurantes. Acuerda con INVU una comisión preferente del 10% antes del cierre. Valor año 1: S/150,000. Comisión: S/15,000. En comparación con el 8% (S/12,000), el Partner gana S/3,000 adicionales. El incentivo para buscar cuentas grandes es claro.', NULL, NULL, NULL, 18);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Partners vs. Referidos – Dos Programas, Dos Perfiles', 'El Programa de Referidos está diseñado para contactos ocasionales que quieren ganar una comisión fija por una referencia simple. El Programa Partners está diseñado para profesionales (contadores, proveedores, consultores, agencias) que tienen una red de contactos activa y quieren monetizar su influencia de manera recurrente. El referido es para abrir una puerta; el Partner es para construir una relación estratégica.', 'Un cliente satisfecho de INVU recomienda a un amigo restaurador. Gana S/1,000. Es un referido. Un contador con 20 clientes restauranteros refiere a 5 de ellos a INVU en un año. Gana S/9,960 en comisiones. Es un Partner. El referido es para contactos sueltos; el Partner es para profesionales con red.', NULL, NULL, NULL, 19);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con 1 Sede', 'Para un negocio de 1 sede, el setup aproximado es S/2,450 y la licencia mensual S/350. Valor año 1: S/2,450 + 12 x S/350 = S/6,650. Comisión 8%: S/532. Pagos: 40% = S/213 (primer pago), 30% = S/160 (60 días), 30% = S/160 (90 días). El Partner cobra S/532 en 3 meses por una referencia que le tomó 1-3 horas de trabajo.', 'Un Partner refiere un restaurante de 1 sede. El cliente firma y paga su primera factura. El Partner recibe S/213 en su primer pago. A los 60 días, S/160. A los 90 días, S/160. Total: S/532. El Partner cobra rápido y sin condiciones. El esfuerzo fue mínimo; la recompensa es concreta.', NULL, NULL, NULL, 20);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con 3 Sedes', 'Para un negocio de 3 sedes, el setup aproximado es S/5,250 y las licencias mensuales S/1,638. Valor año 1: S/5,250 + 12 x S/1,638 = S/24,898. Comisión 8%: S/1,992. Pagos: 40% = S/797, 30% = S/598, 30% = S/598. El Partner cobra S/1,992 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es de S/664 a S/1,992 por hora.', 'Un contador refiere a un cliente que tiene 3 restaurantes. El cliente necesita centralización y facturación electrónica nativa. INVU cierra la venta. El contador recibe S/797 en su primer pago, S/598 a los 60 días, y S/598 a los 90 días. Total: S/1,992. El contador, que invirtió 3 horas en hacer la presentación, tiene un retorno de S/664 por hora.', NULL, NULL, NULL, 21);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con 10 Sedes', 'Para una cadena de 10 sedes, el setup aproximado es S/10,150 y las licencias mensuales S/5,463. Valor año 1: S/75,708. Comisión 8%: S/6,057. Pagos: 40% = S/2,423, 30% = S/1,817, 30% = S/1,817. El Partner cobra S/6,057 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es de S/2,019 a S/6,057 por hora.', 'Un proveedor de insumos refiere una cadena de 10 restaurantes. INVU cierra la venta. El proveedor recibe S/2,423 en su primer pago, S/1,817 a los 60 días, y S/1,817 a los 90 días. Total: S/6,057. El proveedor, que invirtió 3 horas en contactar al dueño de la cadena, tiene un retorno de S/2,019 por hora. Su red de contactos se convierte en una máquina de generar dinero.', NULL, NULL, NULL, 22);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con Cuenta Estratégica', 'Para una cuenta estratégica de más de 15 sedes, el valor año 1 puede superar los S/132,000. Con comisión preferente del 10%, la comisión es de S/13,200+. Pagos: 40% = S/5,280, 30% = S/3,960, 30% = S/3,960. El Partner cobra más de S/13,000 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es excepcional.', 'Un consultor refiere una cadena de 20 restaurantes. Acuerda una comisión preferente del 10% con INVU. Valor año 1: S/150,000. Comisión: S/15,000. El consultor recibe S/6,000 en su primer pago, S/4,500 a los 60 días, y S/4,500 a los 90 días. Total: S/15,000. El consultor, que invirtió 3 horas en contactar al CEO de la cadena, tiene un retorno de S/5,000 por hora. Su red de contactos se convierte en una fuente de ingresos principal.', NULL, NULL, NULL, 23);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'La Comparación con Otros Programas de Partners', 'Otros programas de partners ofrecen comisiones del 5% al 15% sobre la venta inicial, pero con condiciones: el cliente debe permanecer mínimo 12 meses, la comisión se paga fraccionada en todo ese período, y hay techos artificiales. INVU ofrece una comisión del 8% sobre el valor total del primer año, sin descuentos que reduzcan la base de cálculo, pago en tres tramos rápidos, protección de oportunidad, y bonos por rendimiento. INVU es más transparente, rápido y rentable.', 'En el programa X, la comisión es del 10%, pero el cliente debe permanecer 12 meses. Si el cliente cancela a los 8 meses, el Partner pierde parte de su comisión. En INVU, el Partner cobra el 40% al primer pago, el 30% a los 60 días, y el 30% a los 90 días. Si el cliente cancela después de los 90 días, el Partner ya cobró todo. El riesgo es menor y la transparencia es mayor.', NULL, NULL, NULL, 24);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Valor del Esfuerzo vs. la Comisión para el Partner', 'El Partner invierte entre 1 y 3 horas para identificar, contactar, presentar y registrar un negocio. Por ese esfuerzo, puede ganar S/532 (1 sede), S/1,992 (3 sedes), S/6,057 (10 sedes), o más de S/10,000 (cuenta estratégica). La tasa de retorno es excepcional: de S/177 a S/10,560 por hora. Si el Partner mantiene una red de contactos activa y refiere negocios regularmente, puede generar ingresos significativos con bajo esfuerzo.', 'Un Partner refiere 3 cadenas de 10 sedes al año. Comisión total: 3 x S/6,057 = S/18,171. Esfuerzo total: 3 x 3 horas = 9 horas. Tasa de retorno: S/2,019 por hora. El Partner gana casi S/18,000 en un año con 9 horas de trabajo. Si refiere 2 cuentas estratégicas, el ingreso supera los S/21,000. El esfuerzo es mínimo; el retorno es alto.', NULL, NULL, NULL, 25);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Riesgo Cero para el Partner', 'El Partner no asume ningún riesgo financiero. No invierte dinero, no firma contratos, no garantiza el pago del cliente. Su único riesgo es que el negocio referido no cierre dentro de los 90 días, lo que significaría que su esfuerzo de 1-3 horas no rinde fruto. Dado que INVU tiene un alto índice de cierre en negocios calificados, este riesgo es muy bajo. El Partner solo gana; nunca pierde.', 'Un Partner identifica un negocio potencial y lo registra. El negocio no cierra dentro de los 90 días por razones ajenas al Partner. El Partner no pierde dinero; solo perdió 3 horas de su tiempo. Pero tiene otros contactos en su red y sigue refiriendo. Eventualmente, uno de sus referidos cierra y cobra su comisión. El riesgo es mínimo y el potencial de ganancia es alto.', NULL, NULL, NULL, 26);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Perfil del Partner Ideal – Profesionales con Red de Contactos', 'El Partner ideal es cualquier profesional con acceso a una red de contactos en el sector gastronómico y retail: contadores, proveedores de insumos, consultores, agencias de marketing, dueños de locales, profesionales del sector. No necesita ser vendedor tecnológico; necesita tener contactos y credibilidad. Su red de contactos es su activo más valioso. Cuanto más amplia y activa sea su red, mayor será su potencial de ingresos.', 'Un contador con 20 clientes restauranteros tiene acceso a una red valiosa. Cada cliente es una oportunidad potencial de referido. Si refiere a 5 de sus clientes a INVU en un año, puede ganar S/9,960 o más. Un proveedor de insumos con 100 clientes restauranteros tiene una red aún más grande. El Partner no necesita vender; solo necesita abrir la puerta. Su red hace el resto.', NULL, NULL, NULL, 27);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Las 7 Preguntas del Partner – Calificar Antes de Referir', 'El Partner debe hacer 7 preguntas de diagnóstico antes de referir un negocio: sector gastronómico o retail, número de sedes, facturación mensual, sistema actual y dolor, tomador de decisión, planes de expansión, y módulos adicionales (fidelización, e-commerce, autoservicio). Estas preguntas aseguran que el negocio califica y que INVU tiene una oportunidad real de cerrar la venta. También le permiten al Partner calcular su comisión potencial.', 'Un Partner contacta a un conocido dueño de una cadena de 5 restaurantes. Antes de referirlo, hace las 7 preguntas: "¿Cuántas sedes tienes? ¿Qué sistema usas hoy? ¿Cómo manejas la facturación electrónica? ¿Tienes planes de abrir más locales?" Al obtener las respuestas, confirma que el negocio califica y que el valor potencial de la comisión es S/1,992. Ahora está motivado para referir el negocio.', NULL, NULL, NULL, 28);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Framework Gravity para el Partner', 'El Partner aplica el Framework Gravity de manera adaptada: Diagnóstico (identificar el negocio y hacer las 7 preguntas), Educación (presentar INVU como el socio estratégico recomendado), Comparación (mostrar que INVU integra todo en un solo sistema), Construcción de Valor (destacar los beneficios: control total, facturación nativa, e-commerce sin comisiones), y Cierre (asegurar la reunión). El Partner no cierra ventas; cierra reuniones.', 'Un Partner identifica un negocio potencial. Hace el diagnóstico: "Tienes 3 locales, pagas Nubefact aparte, no centralizas inventario." Educa: "Te recomiendo INVU, el sistema que usan más de 5,000 restaurantes en Latam." Compara: "Otros sistemas te cobran la facturación aparte; INVU lo incluye." Construye valor: "Con INVU, centralizas tus 3 locales en un solo panel." Cierra: "¿Qué te parece si los contacto para que te hagan una demo?" El Partner asegura la reunión y su comisión está en marcha.', NULL, NULL, NULL, 29);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Registro Correcto – Protege tu Comisión', 'El Partner debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com, incluyendo: nombre del negocio, nombre y cargo del tomador de decisión, teléfono y correo de contacto, número de sedes, facturación aproximada, sistema actual, y necesidades identificadas. Sin este registro, la comisión del Partner no está protegida. Lo que no está registrado, no existe.', 'Un Partner asegura una reunión con un dueño de una cadena de 10 sedes, pero no envía el correo de registro. Otro Partner registra el mismo negocio. El primero pierde la comisión de S/6,057. El segundo cobra. El primer Partner aprende la lección: lo que no se registra, no existe. A partir de ese momento, registra todas sus oportunidades inmediatamente.', NULL, NULL, NULL, 30);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "No Necesito Cambiar" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "no necesito cambiar mi sistema". La respuesta es validar su postura, pero luego preguntar: "¿Tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? ¿Tienes e-commerce propio sin comisiones?" Si el cliente responde que no, el Partner puede mostrar que INVU es una mejora, no solo un cambio.', 'Un Partner le dice a un restaurador: "Entiendo. Pero ¿tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. Te recomiendo que al menos los conozcas, no pierdes nada." El restaurador, que paga Nubefact aparte y no centraliza su inventario, acepta la reunión.', NULL, NULL, NULL, 31);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Es Caro" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "es caro". La respuesta es validar su preocupación, pero luego mostrar que cuando se suman los costos de facturación electrónica aparte, soporte, sistemas separados, y comisiones de delivery apps, INVU termina siendo más barato o igual. Además, el control de inventario y la reducción de mermas pagan la inversión.', 'Un Partner le dice a un restaurador: "Yo conozco el sistema y sé que cuando sumas lo que pagas por facturación electrónica aparte, por soporte, por sistemas separados, y por comisiones de delivery apps, termina siendo más barato o igual. Además, el control que te da en inventario y la reducción de mermas pagan la inversión. Vale la pena conocerlos." El restaurador, que no había sumado todos los costos, acepta la reunión.', NULL, NULL, NULL, 32);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Lo Voy a Pensar" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "lo voy a pensar". La respuesta es validar que es normal, pero ofrecer una demo sin compromiso: "Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada." Esto quita presión y permite que el cliente avance en el proceso sin sentirse forzado.', 'Un Partner le dice a un restaurador: "Es normal. Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada. ¿Qué te parece?" El restaurador, que se sentía presionado a decidir, se relaja y acepta la demo.', NULL, NULL, NULL, 33);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Ya Tengo un Amigo que me Recomendó Otro Sistema" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice que ya tiene otra recomendación. La respuesta es no descalificar la otra opción, sino ofrecer una comparación informada: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada."', 'Un Partner le dice a un restaurador: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada. ¿Te parece?" El restaurador, que no quería cerrarse a una sola opción, acepta conocer a INVU.', NULL, NULL, NULL, 34);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción del Partner "No Sé Vender"', 'El Partner que dice "no sé vender" debe recordar que no necesita vender. Solo necesita abrir la puerta y presentar a INVU. INVU es el que cierra. El único trabajo del Partner es conectar y asegurar la reunión. Eso lo puede hacer cualquier profesional con contactos en la industria, sin importar su experiencia en ventas. Además, el 8% del valor del primer año del cliente es una comisión justa por abrir esa puerta. Vale la pena el esfuerzo.', 'Un contador duda en referir a sus clientes porque cree que necesita saber vender. Pero luego recuerda: "No necesito vender. Solo necesito abrir la puerta y presentar a INVU. INVU es el que cierra. Mi único trabajo es conectar y asegurar la reunión. Además, el 8% del valor del primer año del cliente es una comisión justa por abrir esa puerta." Con esta mentalidad, contacta a su primer cliente restaurantero y agenda una reunión con INVU.', NULL, NULL, NULL, 35);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Los Niveles de Dominio del Partner', 'El Partner pasa por 4 niveles: Básico (identifica oportunidades pero no las registra, pierde comisiones), Medio (presenta y registra, protege su comisión), Alto (construye una red activa, refiere negocios regularmente, genera S/10,000+ anuales), y Gravedad Cero (se convierte en partner estratégico, con ingresos recurrentes, reconocimiento de INVU, y comisiones que superan los S/20,000 anuales). El objetivo es llegar a Gravedad Cero: ser un socio estratégico de INVU.', 'Básico: Conoce a un restaurador pero no lo refiere formalmente. Pierde la comisión.
Medio: Refiere a un restaurador de 3 sedes, registra la oportunidad, y cobra S/1,992.
Alto: Refiere a 5 clientes al año, todos registrados, ganando S/9,960 anuales.
Gravedad Cero: Tiene una red de 20 contactos en la industria, refiere 10 negocios al año (incluyendo cuentas grandes), gana S/50,000+ anuales, e INVU lo reconoce como un aliado de crecimiento. Su recomendación tiene peso en la industria.', NULL, NULL, NULL, 36);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Potencial de Ingresos Ilimitado del Partner', 'El Partner puede referir múltiples negocios y acumular comisiones sin límite. No hay tope de ingresos ni restricción de cantidad de referidos. Cuantos más negocios conecte, más comisiones acumula. Si refiere negocios grandes (3-10 sedes), sus comisiones pueden superar los S/20,000 o S/50,000 anuales. El potencial de ingresos es ilimitado y está directamente ligado al tamaño y cantidad de los negocios que refiere.', 'Un Partner refiere 5 negocios de 3 sedes al año: 5 x S/1,992 = S/9,960.
Si refiere 3 cadenas de 10 sedes: 3 x S/6,057 = S/18,171.
Si refiere 2 cuentas estratégicas con comisión preferente: 2 x S/10,560+ = S/21,120+.
Si refiere múltiples clientes y acumula más de 20 sucursales en 3 meses, gana bonos de S/2,000 adicionales.
El potencial de ingresos es ilimitado. El Partner que construye una red activa y refiere negocios grandes puede generar ingresos equivalentes a un salario anual completo con un esfuerzo mínimo.', NULL, NULL, NULL, 37);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Programa Partners como Extensión del Equipo de Ventas', 'El programa de partners convierte a los partners en una extensión del equipo de ventas de INVU, ampliando su alcance en el mercado peruano sin costo fijo. Los partners abren puertas que el equipo comercial no podría abrir por sí mismo, aprovechando la confianza y las relaciones personales en la industria. Esto acelera el crecimiento de INVU y genera beneficios para todos. Los partners ganan comisiones significativas; INVU gana clientes calificados; el ecosistema crece.', 'El equipo de ventas de INVU no puede contactar a todos los restaurantes de Lima. Pero 100 partners, cada uno con 10 contactos en la industria, pueden abrir 1,000 puertas. El programa de partners multiplica el alcance comercial de INVU, generando más oportunidades de venta y más ingresos para los partners. INVU crece; los partners cobran comisiones; la red se expande. Todos ganan.


# PÍLDORAS DE CONOCIMIENTO - PROGRAMA HUNTERS INVU POS PERÚ', NULL, NULL, NULL, 38);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Hunter – Cazador, No Esperador', 'El Hunter no espera leads; sale a la calle a identificar negocios, contactar tomadores de decisión, presentar el valor de INVU y cerrar ventas. El Hunter es un cazador de oportunidades que construye su propio mercado. Su ingreso depende directamente de su esfuerzo: 15 visitas/semana, 10 reuniones con decisores, 5 demos/mes, 2-3 cierres/mes. El que no visita, no vende.', 'Un Hunter inicia su semana con una agenda de 15 visitas a restaurantes. No espera que el teléfono suene; sale a la calle, entra a los locales, identifica al dueño o gerente, y hace su pitch. En la primera semana, logra 5 reuniones. En la segunda, 3 demos. En la tercera, 2 cierres. Su ingreso: S/4,298. El Hunter que espera, no cobra. El que caza, triunfa.', NULL, NULL, NULL, 39);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Ritmo del Hunter Ganador – La Disciplina que Multiplica Ingresos', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito. El ritmo es la disciplina que separa al Hunter promedio del Hunter Elite.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base S/2,958 + comisiones S/490 + bono S/850 + MRR S/252 = S/4,550. El esfuerzo se traduce en dinero. El que no visita, no vende.', NULL, NULL, NULL, 40);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'El Pitch de 30 Segundos – La Puerta de Entrada', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?". El pitch debe memorizarse y adaptarse al contexto del cliente.', 'Un Hunter entra a un restaurante y dice: "INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable." El dueño, que ha estado batallando con su facturación electrónica, responde: "¿Cómo lo vemos?" El Hunter ya tiene la reunión.', NULL, NULL, NULL, 41);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Las 7 Preguntas del Hunter – El Mapa del Tesoro', 'El Hunter tiene 7 preguntas que revelan la calificación del cliente, sus dolores y los módulos que necesita. Sin estas preguntas, el Hunter está navegando sin mapa. Las preguntas cubren: facturación y sedes, sistema actual y dolor, facturación electrónica, recetas costeadas, número de cajas, delivery y ecommerce, y tomador de decisión y timeline. El diagnóstico es el mapa; el cierre es el tesoro.', 'En una primera reunión, el Hunter hace las 7 preguntas en 5 minutos. Descubre que el cliente tiene 3 sedes, paga Nubefact aparte, no tiene recetas costeadas, y quiere implementar QR y fidelización. El Hunter sabe exactamente qué cotizar: INVU Central + 3 licencias Sucursal + QR + Loyalty. El diagnóstico es el mapa; el cierre es el tesoro.', NULL, NULL, NULL, 42);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'La Escalera Base – Protección y Motivación para el Hunter', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas. La escalera es el colchón que permite al Hunter aprender y crecer sin miedo.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258. No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', NULL, NULL, NULL, 43);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-3-invu', 'Partners INVU', 'Comisiones desde la Venta 4 – El Ingreso sin Techo', 'Desde la cuarta venta, el Hunter gana 10% sobre setup facturado y pagado, 3% MRR mensual sobre licencias activas durante 12 meses, y 3% sobre hardware. Las comisiones se suman a la base, no la reemplazan. El ingreso del Hunter no tiene techo: cada venta adicional es puro ingreso incremental. Es el combustible que impulsa al Hunter a buscar más y más ventas.', 'Un Hunter cierra 7 ventas en un mes. Base: S/2,958. Comisiones de setup de las ventas 4 a 7: 10% de S/700 = S/980. Bono Top Performer: S/1,020. Cola MRR de las licencias activas: S/504. Ingreso total: S/5,462. Cada venta adicional es puro ingreso extra. No hay techo.', NULL, NULL, NULL, 44);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El MRR – Ingresos Pasivos que se Construyen Mes a Mes', 'El 3% MRR se paga mensualmente durante 12 meses sobre las licencias activas de cada cliente que el Hunter trajo. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional. El MRR es el sueño del vendedor: ingresos que llegan sin esfuerzo adicional.', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin esfuerzo adicional.', NULL, NULL, NULL, 1);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Los Bonos – Gasolina Extra para el Esfuerzo', 'Bonos escalonados: Bono de Inicio S/408 (3 ventas en primer mes), Ejecutivo Ideal S/850 (5 ventas/mes), Top Performer S/1,020 (7 ventas/mes), Bono Trimestral S/3,400 (promedio 10 ventas/mes). Los bonos transforman un buen mes en un mes excepcional y recompensan la consistencia. Son la gasolina que impulsa al Hunter a ir más allá de la meta mínima.', 'Un Hunter tiene un mes con 7 ventas. Base: S/2,958. Comisiones: S/980. Bono: S/1,020. Total: S/4,958. Si mantiene 10 ventas/mes en el trimestre, gana S/3,400 adicionales. La diferencia entre 5 y 7 ventas es S/170 de bono extra; entre 7 y 10, el bono trimestral de S/3,400. El esfuerzo adicional se paga solo.', NULL, NULL, NULL, 2);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', '"Venta Grande Vale por Tres" – Apunta a lo Grande', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (ej. una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio. Una venta grande puede catapultar el ingreso del Hunter en un solo mes.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas.', NULL, NULL, NULL, 3);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre. La consistencia es la clave para escalar al nivel Elite.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', NULL, NULL, NULL, 4);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Comparación con Números – El Argumento del Ahorro', 'El Hunter debe comparar INVU con las alternativas del mercado peruano con datos concretos. Sumar el costo del PSE externo, el soporte aparte y las horas de configuración que la competencia no incluye. Mostrar que INVU (S/350/mes todo incluido) es más barato que la competencia (S/450/mes con PSE y soporte). La diferencia de S/100 es el 0.2% de la facturación de un restaurante de S/50,000. Los números son el arma más poderosa del Hunter.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene. Esa diferencia de S/100 al mes es el 0.2% de tu facturación."', NULL, NULL, NULL, 5);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Objeción "Es Caro" – El Protocolo Gravity en Acción', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity para "es caro" tiene 5 pasos: Validar (entiendo que el precio es importante), Diagnosticar (¿qué te parece caro exactamente?), Reencuadrar (cuando sumas el PSE, el costo real es mayor), Micro-cierre (¿te parece si hacemos el cálculo con tus números?), y Cierre (¿qué día te acomoda para la demo?). Este protocolo convierte la objeción en una oportunidad de cierre.', 'Cliente: "Es caro."  
Hunter:  
"Entiendo que el precio es una consideración importante."  
"¿Qué es lo que te parece caro exactamente, el setup o las licencias mensuales?"  
"Cuando sumas lo que pagas por Nubefact (S/120/mes), soporte (S/80/mes) y sistemas separados, el costo real de la competencia es S/450/mes. INVU es S/350/mes todo incluido."  
"¿Te parece si hacemos el cálculo con tus números actuales?"  
"¿Qué día te acomoda para la demo?"', NULL, NULL, NULL, 6);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Objeción "Ya Tengo un POS" – Diagnosticar el Dolor Oculto', 'El cliente que dice "ya tengo un POS" no está cerrado; está diciendo que no ve razón para cambiar. El Hunter debe diagnosticar qué le falta a su sistema actual. Preguntas: "¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real?" Si no tiene esas funcionalidades, INVU es una mejora, no un cambio. El dolor oculto es la llave para abrir la venta.', '"Me alegra que tengas un sistema. ¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. No se trata de cambiar por cambiar. Se trata de tener una operación rentable."', NULL, NULL, NULL, 7);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Objeción "Lo Voy a Pensar" – El Costo de la Postergación', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El Hunter debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, y cerrar ofreciendo una demo sin compromiso. El costo de postergar es el argumento que mueve al cliente a actuar.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos."', NULL, NULL, NULL, 8);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Setup – Inversión, No Gasto', 'El setup de INVU es un desembolso inicial que muchos clientes ven como un gasto. El Hunter debe reencuadrarlo como una inversión que ahorra meses de operación rota. La competencia no cobra setup porque no hace nada: da el software y el cliente lo configura. INVU cobra setup porque deja el restaurante operando desde el día uno. El setup es inversión, no gasto. Esta reencuadre cambia la percepción del cliente.', '"Entiendo que el setup es un desembolso inicial importante. Ese setup lo pagás una vez y te ahorra meses de operación rota. Además te lo podemos plantear como facturación anual con mejor precio. La competencia no cobra setup porque no hace nada: te dan el software y tú lo configuras. INVU te deja el restaurante operando desde el día uno. El setup es inversión, no gasto."', NULL, NULL, NULL, 9);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al Hunter profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al Hunter con datos reales. Lo que no está en CRM, no existe. Esta es la regla de oro del Hunter.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', NULL, NULL, NULL, 10);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Caso del Restaurante con Facturación Externa y Múltiples Sedes – El Cliente Ideal', 'Un cliente con 3 sedes que paga Nubefact aparte y no tiene control centralizado es el cliente ideal para INVU. El Hunter debe mostrar que el costo actual (S/1,110/mes) es solo un poco menor que INVU (S/1,862/mes), pero que INVU incluye centralización, FE nativa, KDS y Loyalty. El ahorro en mermas (2% = S/2,400/mes) y comisiones de delivery cubren la diferencia. Este caso es el ejemplo perfecto para demostrar el ROI de INVU.', '"Entiendo que el costo de INVU es mayor que lo que pagas hoy. Hoy pagas S/1,110 mensuales: S/750 por los 3 POS y S/360 por Nubefact. Con INVU, el costo mensual es S/1,862, que incluye centralización, FE nativa, KDS y Loyalty. La diferencia es S/752, que es el 0.6% de tu facturación mensual. Pero lo que no estás viendo es lo que te cuesta no tener centralización: precios desactualizados, inventario que no cuadra, mermas sin control. Si reducimos tus mermas en un 2%, son S/2,400 mensuales de ahorro. La inversión se paga sola."', NULL, NULL, NULL, 11);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Los Errores que Matan la Venta – Lo que el Hunter Debe Evitar', 'Hay 6 errores comunes que el Hunter debe evitar: Hablar de precio antes de diagnosticar; hacer una demo genérica sin enfocarse en el dolor; no sumar los costos ocultos de la competencia; no comparar con la competencia local; no cerrar con una pregunta de avance; hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza". Evitarlos es el primer paso para ser un Hunter Elite.', 'Un cliente pregunta: "¿Cuánto cuesta?"  
El Hunter novato responde: "S/350/mes." El cliente dice: "Es caro." Se va.  
El Hunter experto responde: "El costo depende de tus necesidades. Permíteme hacerte algunas preguntas para entender tu operación y darte una cotización precisa. ¿Cuántas sedes tienes? ¿Qué sistema usas hoy?" El cliente se queda, responde, y el Hunter construye valor antes de dar el precio.', NULL, NULL, NULL, 12);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Los Niveles de Dominio – De Básico a Gravedad Cero', 'El Hunter pasa por 4 niveles: Básico (explica el producto sin conectar beneficios), Medio (conecta beneficios y diagnostica), Alto (justifica el precio y maneja objeciones con autoridad), y Gravedad Cero (controla la conversación y cierra con autoridad, sin descuentos). El objetivo es llegar a Gravedad Cero: ser un asesor estratégico del restaurantero, no un vendedor más. Cada nivel es un escalón que el Hunter debe subir con disciplina y práctica.', 'Básico: "INVU tiene facturación electrónica nativa."  
Medio: "INVU incluye FE nativa, así que te ahorras S/120/mes en Nubefact."  
Alto: "Cuando sumas el PSE, soporte y sistemas separados, la competencia te cuesta S/450/mes. INVU es S/350/mes todo incluido. Y el onboarding consultivo te da visibilidad de márgenes que nunca tuviste."  
Gravedad Cero: El cliente dice: "¿Qué necesito firmar?" El Hunter ya no vende; el cliente compra porque confía en él.', NULL, NULL, NULL, 13);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Potencial de Ingresos del Hunter – Sin Techos, Sin Límites', 'El Hunter tiene un potencial de ingresos ilimitado. Desde S/35,496 anuales (3 ventas/mes) hasta más de S/100,000 anuales (Hunter Elite con cuentas grandes). El ingreso está directamente ligado al esfuerzo y la consistencia. No hay techos artificiales; el cielo es el límite. Cada venta adicional es puro ingreso incremental. El Hunter que entiende esto, se motiva a dar siempre un paso más.', '3 ventas/mes: S/35,496 anuales.  
5 ventas/mes: S/51,576 a S/60,576 anuales.  
7 ventas/mes: S/65,544 a S/77,496 anuales.  
10 ventas/mes: S/84,708 a S/108,612 anuales.  
Hunter Elite con cuentas grandes: S/100,000+ anuales.  
El potencial es ilimitado. El Hunter que construye una cartera de clientes y mantiene un ritmo constante, puede generar ingresos equivalentes a un salario ejecutivo.', NULL, NULL, NULL, 14);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Valor del Onboarding Consultivo para el Hunter', 'El onboarding consultivo de INVU es un diferenciador clave que el Hunter debe comunicar. INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación rentable: menú con recetas costeadas, materia prima, proveedores, márgenes reales por plato. Muchos dueños operan a ciegas: no saben cuánto ganan por plato, no controlan mermas. El onboarding consultivo transforma al vendedor en un asesor de confianza y es un argumento de cierre poderoso.', '"No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca ha visto el margen real de sus platos, percibe a INVU como un socio, no como un proveedor.', NULL, NULL, NULL, 15);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Soporte Local 24/7 – El Seguro de Continuidad para el Cliente', 'INVU tiene equipo de soporte en Perú, con WhatsApp directo a un humano, soporte remoto y en sitio. La competencia tiene tickets de 24-48 horas y soporte desde otro país. Cuando el sistema falla un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. El Hunter debe vender esto como tranquilidad operativa. Es un argumento que la competencia no puede igualar.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El Hunter responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma." El cliente se siente seguro.', NULL, NULL, NULL, 16);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Ecosistema Móvil Nativo – El Negocio en el Bolsillo del Dueño', 'INVU ofrece tres apps nativas: POS para operar, Reports para medir desde cualquier lugar, y Supply para inventario y compras desde el móvil. La competencia encadena al usuario a una sola pantalla fija. El Hunter debe comunicar que INVU libera al dueño de la obligación de estar presente para controlar su negocio. Es el sueño del emprendedor: control total desde la palma de la mano.', '"Con INVU, tu negocio vive donde vos estés. Operás desde cualquier dispositivo con INVU POS, medís tus ventas y movimientos con INVU Reports desde tu celular, y gestionás compras e inventario con INVU Supply. No estás encadenado a una caja fija. Puedes estar en casa o de viaje y saber exactamente cómo va tu operación."', NULL, NULL, NULL, 17);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Ecosistema Integrado sin Comisiones – El 100% es para Ti', 'INVU integra POS, KDS, inventario, QR, kioskos, loyalty y e-commerce en una sola plataforma, con e-commerce propio sin comisiones por venta. La competencia cobra comisiones de 25-30% por delivery. El Hunter debe mostrar que INVU permite vender sin ceder margen a terceros, lo que multiplica la rentabilidad del cliente. Es una propuesta de valor que la competencia no puede ofrecer.', '"No necesitas cinco sistemas diferentes. INVU integra POS, inventario, facturación, QR, kioskos, loyalty y e-commerce en una sola plataforma. Y tu tienda online no paga comisiones: el 100% de la venta es para ti. Un solo sistema, un solo costo, cero comisiones. Lo que antes perdías en Rappi, ahora lo ganas."', NULL, NULL, NULL, 18);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El KPI del Hunter – De Discovery a Cotización', 'El KPI principal del Hunter no es cuántas demos se hacen, sino cuántos clientes pasan de discovery a cotización. Ahí está la conversión real. El Hunter debe enfocar sus esfuerzos en calificar oportunidades y avanzarlas en el pipeline. Una demo sin cotización es una oportunidad perdida. El objetivo es convertir cada oportunidad calificada en una cotización y cada cotización en un cierre.', 'Un Hunter hace 5 demos al mes, pero solo convierte 2 en cotizaciones. Su tasa de conversión es del 40%. Otro Hunter hace 5 demos y convierte 4 en cotizaciones (80%). Su ingreso es el doble. El KPI es la conversión, no la actividad. El Hunter debe enfocarse en calificar mejor y avanzar más rápido las oportunidades.


# PÍLDORAS DE CONOCIMIENTO - HARDWARE Y PROCESO DE VISITA TÉCNICA INVU POS', NULL, NULL, NULL, 19);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica – No es un Trámite, es una Herramienta de Ventas', 'La visita técnica en INVU POS no es un simple trámite de instalación. Es una herramienta estratégica de consultoría que se sitúa entre la validación comercial inicial y la cotización definitiva, permitiendo al Hunter demostrar profesionalismo, identificar necesidades adicionales de hardware y garantizar una implementación exitosa desde el día uno. El Hunter que entiende esto no ve la visita como una obligación, sino como una oportunidad de cerrar con autoridad.', 'Un Hunter ha cerrado la demo y el cliente está interesado, pero duda por el precio. El Hunter dice: "Antes de darte la cotización definitiva, nuestro especialista técnico va a evaluar tu local sin costo. Te va a decir qué hardware puedes reutilizar y qué necesitas para que tu operación funcione sin interrupciones. Con ese informe, te doy una cotización precisa y te aseguro que desde el día uno estarás operando." El cliente, que ve profesionalismo, acepta la visita y el Hunter usa el informe para cerrar.', NULL, NULL, NULL, 20);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica como Auditoría Operativa Integral', 'La visita técnica es una auditoría operativa integral que evalúa tres dimensiones críticas: conectividad (velocidad de internet, estabilidad del enlace, cobertura WiFi), equipamiento (impresoras, balanzas, cajones, lectores), y red de trabajo (topologías de red local, ruteo de cables, ubicación de estaciones). No es una inspección superficial; es una evaluación profunda que garantiza que el sistema funcionará desde el día uno.', 'El especialista de INVU llega al local del cliente. No solo mira la impresora; la prueba, mide la velocidad del internet, camina por todo el local con un medidor de WiFi, revisa los cables, y evalúa dónde debería ir la caja y la pantalla KDS. Al final, entrega un informe detallado. El cliente queda impresionado porque nunca nadie había hecho una evaluación tan completa. La confianza en INVU se multiplica.', NULL, NULL, NULL, 21);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica – Consultoría Gratuita, no Inspección de Control', 'INVU no envía a un técnico a revisar si el cliente cumple requisitos para negarle el servicio. Envía un especialista para asegurar que la implementación sea 100% exitosa y para hacer recomendaciones personalizadas según el flujo de operación del negocio. El Hunter debe comunicar esto como un valor agregado, no como una inspección.', 'Un cliente dice: "¿Van a venir a revisar mi local para ver si cumplo con requisitos?" El Hunter responde: "No es una inspección. Es una consultoría gratuita. Nuestro especialista viene a asegurarse de que tu implementación sea exitosa. Te va a recomendar qué hardware puedes reutilizar y qué mejoras te van a ayudar a operar sin problemas. No es para negarte el servicio; es para que funcione perfectamente desde el día uno."', NULL, NULL, NULL, 22);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Reutilización de Hardware – Confianza y Ahorro para el Cliente', 'A diferencia de muchos POS que obligan al cliente a comprar todo el hardware nuevo, INVU evalúa lo que el cliente ya tiene y recomienda reutilizar todo lo que sea compatible (impresoras, lectores, cajones). Esto ahorra dinero al cliente y construye confianza. El Hunter debe comunicar esto como un gesto de honestidad, no como una concesión.', 'El cliente dice: "No quiero comprar impresoras nuevas." El Hunter responde: "No vamos a obligarte a comprar hardware nuevo si lo que tienes funciona. Nuestro especialista va a revisar tus impresoras, lectores y cajones, y te va a recomendar reutilizar todo lo que sea compatible. Así ahorras en la inversión inicial y solo compras lo que realmente necesitas." El cliente confía en el vendedor porque no le está vendiendo algo que no necesita.', NULL, NULL, NULL, 23);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Evaluación de Conectividad – El Combustible del Sistema', 'El internet es el combustible de INVU POS. Si la red falla, el sistema no opera, las ventas se pierden y el cliente se frustra. El especialista técnico evalúa la velocidad del internet contratado, la estabilidad del enlace de datos, y mapea la cobertura WiFi del recinto comercial, identificando puntos muertos. El Hunter debe comunicar que esta evaluación es esencial para la continuidad del negocio.', '"La velocidad es solo una parte. También evaluamos la estabilidad, la latencia, y la cobertura WiFi en toda el área del local. A veces el internet es rápido pero la señal no llega a la cocina, o se cae en horas pico. Nuestro especialista va a medir todo eso para asegurarse de que no tengas puntos ciegos." El cliente, que ha tenido caídas en horas pico, valora la evaluación.', NULL, NULL, NULL, 24);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Fibra Óptica vs. Coaxial – La Diferencia que Afecta la Operación', 'INVU recomienda fibra óptica (FTTH) para estabilidad y baja latencia. Coaxial (HFC) genera latencia inestable y no es recomendado para operaciones de alta demanda. El Hunter debe saber esto para recomendar la mejora si el cliente tiene coaxial. Esta recomendación puede evitar problemas críticos en la operación.', 'Durante la visita, el especialista detecta que el cliente tiene internet coaxial. Le explica: "El coaxial es inestable y puede generar latencia en horas pico, lo que afectaría tu sistema y tus integraciones con delivery. Te recomendamos migrar a fibra óptica para garantizar estabilidad. Es una inversión que te ahorrará dolores de cabeza." El cliente, que no sabía la diferencia, valora la recomendación profesional.', NULL, NULL, NULL, 25);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Router 4G/5G de Respaldo – El Seguro de Continuidad', 'Para comercios con alta demanda de delivery e integraciones, INVU recomienda instalar un router con chip 4G/5G de contingencia automática que asegura operación continua si el internet principal falla. El Hunter debe vender esto como un seguro, no como un lujo. Es la garantía de que el negocio nunca se detiene.', '"Tu internet puede fallar, pero tu negocio no debe detenerse. Por eso recomendamos un router con chip 4G de respaldo. Si el internet principal se cae, el sistema cambia automáticamente al respaldo y sigues operando sin perder una venta. Es tu seguro de continuidad." El cliente, que ha perdido ventas por cortes de internet, ve el valor inmediato y acepta la recomendación.', NULL, NULL, NULL, 26);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Hardware Homologado – Impresora 3nStar RPT004', 'INVU recomienda la impresora 3nStar RPT004 como hardware oficial por su altísima resistencia térmica y doble interfaz (USB/LAN), garantizando durabilidad y compatibilidad. Una impresora que se traba genera caos en la operación. El Hunter debe comunicar que el hardware homologado es una inversión en estabilidad, no un gasto.', '"Recomendamos la impresora 3nStar RPT004 porque es la que hemos probado y validado para funcionar perfectamente con INVU. Es resistente, rápida y tiene doble conexión USB/LAN, así que no se desconecta. Es una inversión que te ahorrará dolores de cabeza a largo plazo." El cliente, que ha sufrido con impresoras que se traban, aprecia la recomendación.', NULL, NULL, NULL, 27);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Evaluación de Topología de Red – La Eficiencia Operativa', 'INVU no solo instala el software en cualquier lugar. Diseña la distribución de los equipos para maximizar la eficiencia operativa: dónde va la caja, dónde va la impresora de comandas, dónde va la pantalla KDS en cocina. Una mala ubicación genera cuellos de botella. El Hunter debe comunicar que la visita técnica optimiza el flujo de trabajo.', '"No solo instalamos el sistema en cualquier lugar. Nuestro especialista diseña la ubicación de cada equipo para que tu operación sea lo más eficiente posible: la caja en el lugar correcto, la impresora de comandas donde la cocina la vea rápido, la pantalla KDS donde el cocinero la tenga a la vista. Así tu personal trabaja más rápido y tus clientes esperan menos."', NULL, NULL, NULL, 28);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Sistema Mesh WiFi – El Fin de los Puntos Muertos', 'Cuando la cobertura WiFi no llega a toda el área del local (especialmente a la cocina o al fondo del restaurante), el especialista recomienda sistemas de red en malla (Mesh WiFi) para eliminar puntos muertos. El Hunter debe comunicar que esto garantiza que el sistema funcione en todo el local, sin interrupciones.', 'Durante la visita, el especialista detecta que la señal WiFi no llega a la cocina. Le dice al dueño: "Tu cocina está en un punto muerto. Los pedidos pueden no llegar a tiempo. Te recomendamos un sistema Mesh WiFi para que la señal llegue a todo el local. Es una inversión pequeña que garantiza que tu operación fluya sin interrupciones."', NULL, NULL, NULL, 29);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Upselling durante la Visita Técnica – +40% de Ticket Promedio', 'Según datos históricos de INVU, la visita técnica genera un +40% de aumento en el ticket medio al identificar necesidades adicionales de hardware que el cliente no había considerado: tablets nuevas, impresoras adicionales, routers mejorados, sistemas Mesh, hardware de respaldo. El Hunter que domina la visita técnica convierte cada visita en una oportunidad de upselling.', 'Un Hunter agenda la visita técnica para un restaurante. El especialista descubre que el WiFi no llega a la cocina, que la impresora es obsoleta, y que el internet es coaxial. El informe recomienda: router Mesh WiFi, impresora 3nStar RPT004, y migración a fibra óptica. El Hunter incluye esto en la cotización, sumando S/1,500 en hardware adicional. Su comisión (10% desde la 4ª venta) aumenta en S/150. El cliente tiene certeza de que el sistema funcionará sin problemas.', NULL, NULL, NULL, 30);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Reducción de Tickets de Soporte – El Beneficio Oculto', 'Al validar técnicamente el local antes de la instalación, INVU evita el 80% de los problemas que generan tickets de soporte en los primeros días. Esto significa clientes más satisfechos, menos llamadas de emergencia, y una experiencia de marca impecable desde el día uno. El Hunter debe comunicar que la visita técnica es una inversión en tranquilidad.', '"La mayoría de los problemas que tienen los clientes de otros POS son por falta de validación técnica: internet lento, hardware incompatible, mala ubicación de equipos. Nosotros prevenimos eso antes de la instalación, para que no tengas sorpresas después. La visita técnica es tu garantía de que el sistema funcionará sin problemas desde el día uno."', NULL, NULL, NULL, 31);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica como Argumento de Cierre', 'El informe técnico resultante de la visita es una herramienta poderosa para el cierre. El Hunter lo usa para armar una cotización precisa con costos de hardware justificados. El informe es un documento con peso técnico que demuestra al cliente que la inversión es necesaria y que INVU es un socio confiable.', 'Un cliente duda sobre la inversión en hardware. El Hunter presenta el informe: "Nuestro especialista validó que tu operación necesita X hardware para funcionar de manera óptima. Te recomendamos esta inversión para garantizar continuidad. Sin esto, tu sistema podría tener fallas en horas pico. Con esto, operas sin interrupciones." El cliente, al ver el informe técnico, acepta la inversión.', NULL, NULL, NULL, 32);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Qué Tipo de Internet Tienen?', 'El Hunter debe preguntar en el discovery: "¿Qué tipo de conexión a internet tienen y qué velocidad contratada?" Fibra óptica (FTTH) es recomendada; coaxial (HFC) genera latencia inestable. Esta pregunta permite al Hunter anticipar problemas y preparar al cliente para posibles mejoras.', 'Un Hunter pregunta: "¿Qué tipo de internet tienen?" El cliente responde: "Coaxial de 100MB." El Hunter sabe que esto puede ser problemático. Dice: "El coaxial puede generar latencia en horas pico. Nuestro especialista lo evaluará en la visita técnica y te recomendará si necesitas migrar a fibra óptica para garantizar estabilidad." El cliente valora la transparencia.', NULL, NULL, NULL, 33);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Qué Hardware Utilizan Actualmente?', 'El Hunter debe preguntar: "¿Qué equipos y hardware utilizan actualmente (marcas, modelos, antigüedad)?" Esto incluye impresoras, tablets, computadoras, lectores, cajones de dinero. Saber esto permite al Hunter dimensionar la reutilización de hardware y preparar al cliente para posibles reemplazos.', 'Un Hunter pregunta: "¿Qué tablets usan?" El cliente responde: "Tablets de 5 años." El Hunter dice: "Entiendo. Nuestro especialista evaluará si aún son funcionales o si necesitan reemplazo. Si funcionan, las reutilizamos; si no, te recomendamos nuevas." El cliente se siente escuchado y confía en el proceso.', NULL, NULL, NULL, 34);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Tienen un Área de Cocina Separada?', 'El Hunter debe preguntar: "¿Tienen un área de cocina o producción separada? ¿Dónde se ubican las estaciones de venta?" Esto permite planificar la ubicación estratégica de los equipos (POS, KDS, impresoras de comandas) y garantizar la eficiencia operativa.', 'Un Hunter pregunta y descubre que la cocina está a 15 metros de la caja. Dice: "Perfecto. Nuestro especialista evaluará la mejor ubicación para la impresora de comandas y la pantalla KDS. Así los pedidos llegan rápido a cocina y tu personal no pierde tiempo." El cliente valora que el Hunter esté pensando en su flujo de trabajo.', NULL, NULL, NULL, 35);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Manejan Delivery o Apps?', 'El Hunter debe preguntar: "¿Manejan delivery o integraciones con apps como Rappi o PedidosYa?" Si el cliente tiene alta demanda de delivery, necesita un enlace de internet más estable y un router con respaldo 4G. Esta pregunta permite al Hunter anticipar necesidades de hardware crítico.', 'El cliente responde: "Sí, movemos S/10,000 al mes por delivery." El Hunter dice: "Excelente. Entonces tu internet debe ser muy estable y tener respaldo. Nuestro especialista evaluará tu red y te recomendará un router 4G de respaldo para que nunca pierdas una venta de delivery." El cliente ve el valor inmediato.', NULL, NULL, NULL, 36);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Diagnóstico', 'El Hunter debe hacer las preguntas de diagnóstico sobre hardware y red durante el discovery o la demo. No debe esperar a la visita técnica para descubrir problemas. El diagnóstico temprano permite preparar al cliente y al especialista técnico, y posiciona al Hunter como un consultor proactivo.', 'En el discovery, el Hunter pregunta sobre internet, hardware y distribución. Al identificar que el cliente tiene coaxial y tablets viejas, dice: "Nuestro especialista evaluará esto en la visita técnica. Te anticipo que podríamos recomendar migrar a fibra óptica y renovar algunas tablets. Pero no te preocupes, evaluaremos todo y te daremos un informe con prioridades."', NULL, NULL, NULL, 37);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Educación', 'El Hunter educa al cliente sobre la importancia de la visita técnica: "Nuestro especialista va a evaluar tu red, hardware y distribución para asegurarse de que la implementación sea 100% exitosa. Esto es parte de nuestro modelo llave en mano. No te dejamos solo con el software; validamos tu infraestructura para que no tengas sorpresas." La educación es clave para que el cliente vea la visita como un valor agregado.', 'Un cliente dice: "No sé si necesito la visita técnica." El Hunter responde: "Es parte de nuestro servicio. No queremos que instales el sistema y descubras que tu internet es lento o que tu hardware no es compatible. Preferimos validar todo antes, para que desde el día uno estés operando sin interrupciones."', NULL, NULL, NULL, 38);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Comparación', 'El Hunter compara con la competencia: "Otros sistemas te entregan el software y tú te las arreglas para que funcione. Si tu internet es lento o tu hardware no es compatible, te das cuenta después de la instalación y pierdes días resolviendo problemas. INVU valida todo antes, para que desde el día uno estés operando sin interrupciones." Esta comparación posiciona a INVU como el socio confiable.', 'El cliente dice: "Mi amigo tiene otro POS y no necesitó visita técnica." El Hunter responde: "Y probablemente tuvo problemas los primeros días. Nosotros preferimos prevenir. La visita técnica es lo que nos diferencia: validamos tu infraestructura antes de instalar, para que no tengas sorpresas."', NULL, NULL, NULL, 39);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Construcción de Valor', 'El Hunter construye valor mostrando los beneficios de la visita técnica: "Con esta evaluación, aseguramos que tu sistema funcione sin caídas, que tu hardware sea el adecuado, que tu personal pueda operar sin frustraciones, y que puedas seguir vendiendo incluso si el internet falla gracias al respaldo 4G. No es un gasto, es una inversión en la continuidad de tu negocio." El valor es la tranquilidad operativa.', '"Imagina que un viernes a las 8pm, en pleno horario pico, el internet se cae. Con el respaldo 4G, tu sistema sigue operando. Esa es la tranquilidad que te da la visita técnica. No perderás una venta por un corte de internet."', NULL, NULL, NULL, 40);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Cierre', 'El Hunter cierra la agenda de la visita técnica: "¿Qué día te acomoda que nuestro especialista vaya a tu local para hacer la evaluación? Es sin costo para ti y te daremos un informe con recomendaciones personalizadas." El cierre es asegurar la visita, que es el paso previo a la cotización y el cierre final.', 'Después de presentar el valor de la visita técnica, el Hunter dice: "¿Qué te parece si agendamos la visita para el próximo martes? El especialista irá a tu local, hará la evaluación, y te dará un informe. Sin compromiso. Después decides qué hardware renovar." El cliente acepta y el Hunter agenda la visita.', NULL, NULL, NULL, 41);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Manejo de la Objeción "No Quiero Invertir en Hardware Nuevo"', 'El cliente que dice "no quiero invertir en hardware nuevo" está preocupado por el costo. El Hunter debe validar, educar sobre la reutilización de hardware, comparar con la competencia (que obliga a comprar todo nuevo), y construir valor mostrando que la inversión se paga sola con la eficiencia ganada.', '"Entiendo. Por eso hacemos la visita técnica: para evaluar qué se puede reutilizar y qué necesita reemplazo. Nuestro especialista te dirá con honestidad qué equipos aún sirven y cuáles te están generando pérdidas de tiempo y dinero. No te vamos a vender algo que no necesites. Y la inversión en hardware nuevo se paga sola con la eficiencia que ganas."', NULL, NULL, NULL, 42);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'El Manejo de la Objeción "¿Por qué Tengo que Pagar por la Visita Técnica?"', 'El cliente que pregunta por el costo de la visita técnica debe ser informado de que es gratuita y parte del modelo llave en mano. El Hunter debe comunicar que la visita técnica es una inversión de INVU para asegurar el éxito del cliente, no un costo adicional.', '"La visita técnica es gratuita para ti. Es parte de nuestro modelo llave en mano. No te cobramos por la evaluación, la incluimos en el setup. Queremos asegurarnos de que tu implementación sea 100% exitosa desde el día uno. No es un gasto, es una inversión nuestra en tu éxito."', NULL, NULL, NULL, 43);
  INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden)
  VALUES (invu_id, 'grupo-4-invu', 'Hardware INVU', 'Los Niveles de Dominio en Hardware y Visita Técnica', 'El Hunter pasa por 4 niveles en el manejo de hardware y visita técnica: Básico (conoce el proceso pero no lo ejecuta proactivamente), Medio (ejecuta la visita como parte del proceso), Alto (usa la visita como herramienta de valor y upselling), y Gravedad Cero (integra la visita en su estrategia de consultoría, anticipa necesidades, y convierte cada visita en una oportunidad de venta adicional, incrementando el setup facturado en un 40% o más).', 'Básico: Sabe que existe la visita técnica, pero no la menciona hasta que el cliente pregunta.  
Medio: Presenta la visita, coordina con el especialista, y usa el informe para la cotización.  
Alto: Posiciona la visita como consultoría gratuita, identifica upselling, y la usa como argumento de cierre.  
Gravedad Cero: Anticipa necesidades de hardware antes de la visita, prepara al cliente, y convierte cada visita en una oportunidad de venta adicional, incrementando el setup en 40% o más. El cliente percibe la visita como un valor agregado.', NULL, NULL, NULL, 44);

  RAISE NOTICE 'Inserted % items for invupos', 176;
END
$$;
